insert into public.words (id, word, romanization, category, secondary_category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, aliases, likes, saves, translations) values
('505', '환불메이크업', 'Hwan-Bul-Me-I-Keu-Eop', 'beauty', 'variety', '어디서든 환불받아 낼 것 같은 인상의 센 메이크업', '{"de": "Make-up so bestimmt, dass man die Rückerstattung garantiert bekommt", "en": "Makeup fierce enough that you''d definitely get the refund", "es": "Un maquillaje tan imponente que seguro te devuelven el dinero", "ja": "どこでも返金してもらえそうな強めメイク", "vi": "Lối trang điểm sắc lạnh đến mức chắc chắn đòi được tiền hoàn"}'::jsonb, '[환불메이크업]', '[{"type": "명사", "examples": [{"de": "Ich muss morgen reklamieren — soll ich das volle Rückerstattungs-Make-up auflegen?", "es": "Mañana tengo que ir a reclamar, ¿me hago el maquillaje de reembolso?", "ja": "明日クレーム言いに行くんだけど、返金メイクして行こうかな?", "vi": "Mai mình phải đi khiếu nại, hay là makeup kiểu ''đòi hoàn tiền'' luôn nhỉ?", "eng": "I have to go complain tomorrow — should I do the full refund-makeup face?", "kor": "내일 항의하러 가야 되는데 환불메이크업 하고 갈까?"}, {"de": "Ich hatte heute ein Vorstellungsgespräch und habe das starke Make-up gemacht. Ich wollte nicht schüchtern wirken.", "es": "Hoy tenía entrevista y me hice el maquillaje de reembolso. No quería parecer tímida.", "ja": "今日面接だから強めメイクにした。気後れしたくなくて。", "vi": "Hôm nay phỏng vấn nên mình makeup kiểu sắc lạnh. Không muốn trông rụt rè.", "eng": "I did refund makeup for my interview today. I didn''t want to look timid.", "kor": "오늘 면접이라 환불메이크업 했어. 기죽기 싫어서."}], "definition": "진한 눈화장과 또렷한 레드 립처럼, 만만해 보이지 않는 강한 인상을 일부러 만드는 메이크업. 잘못한 것도 없는데 환불하러 갈 때 이상하게 주눅이 드는 경험에서 나온 말로, 그럴 때 무장하듯 하고 가는 화장이라는 뜻이다. 실제 항의하러 갈 때만 쓰는 게 아니라, 면접·발표처럼 기죽으면 안 되는 자리의 화장을 가리킬 때도 쓴다.", "definition_i18n": {"de": "Ein bewusst starker Look — kräftiges Augen-Make-up, ein entschiedener roter Lippenstift —, damit man nicht als jemand wirkt, über den man hinweggeht. Er stammt von der seltsamen Erfahrung, sich beim Einfordern einer Rückerstattung klein zu fühlen, obwohl man nichts falsch gemacht hat: Dieses Gesicht legt man wie eine Rüstung an. Nicht nur für echte Reklamationen — auch für Vorstellungsgespräche, Präsentationen, jeden Anlass, bei dem man sich nicht ducken darf.", "en": "A deliberately strong look — heavy eye makeup, a decisive red lip — built so you do not read as a pushover. It comes from the odd experience of feeling small when going to ask for a refund even though you did nothing wrong; this is the face you put on as armour. It is not only for actual complaints: people use it for job interviews, presentations, any occasion where you cannot afford to shrink.", "es": "Un look deliberadamente contundente —ojos cargados, labio rojo rotundo— montado para que no te tomen por alguien a quien pisar. Viene de esa experiencia rara de sentirse pequeña al ir a pedir un reembolso aun sin haber hecho nada mal: es la cara que te pones como armadura. No es solo para reclamaciones reales; también se usa para entrevistas de trabajo, presentaciones y cualquier situación en la que no puedas encogerte.", "ja": "濃いアイメイクにくっきりした赤リップのように、なめられない強い印象をわざと作るメイク。何も悪くないのに返金を求めに行くとなぜか気後れする、あの経験から生まれた語で、そんなとき武装するように施していく化粧という意味。実際に抗議に行くときだけでなく、面接やプレゼンなど気圧されてはいけない場面の化粧を指すのにも使う。", "vi": "Lối trang điểm cố tình mạnh mẽ — mắt đánh đậm, môi đỏ dứt khoát — dựng lên để không bị xem là dễ bắt nạt. Nó bắt nguồn từ trải nghiệm kỳ lạ khi ta thấy mình nhỏ bé lúc đi đòi hoàn tiền dù chẳng làm gì sai; đây là gương mặt bạn khoác lên như áo giáp. Không chỉ dùng cho việc khiếu nại thật: người ta còn dùng cho phỏng vấn, thuyết trình, bất cứ dịp nào không được phép co mình lại."}}]'::jsonb, '''환불''과 ''메이크업''을 붙인 말. 뿌리가 되는 표현 ''환불원정대''가 먼저인데, 나무위키에 따르면 2008~2009년 무렵 여초 커뮤니티에서 ''이 사람들이 항의하면 어느 매장에서든 환불해 줄 것 같다''는 뜻으로 《반지의 제왕》 반지원정대를 비틀어 쓰이던 말이다. 2020년 MBC 《놀면 뭐하니?》의 프로젝트 걸그룹이 이 이름을 가져다 쓰면서 전 국민이 아는 말이 됐다 — 즉 예능이 말을 만든 게 아니라 이미 있던 말을 빌려 쓴 쪽이다.', '{"de": "환불 (Rückerstattung) + 메이크업. Der Ursprungsausdruck 환불원정대 kam zuerst: laut Namuwiki kursierte er um 2008–2009 in überwiegend weiblichen Online-Communities, angelehnt an die Gefährten des Rings, für Leute, denen jeder Laden auf den ersten Blick Geld zurückgeben würde. 2020 lieh sich die MBC-Show Hangout with Yoo den Namen für ihre Projekt-Girlgroup, was ihn landesweit bekannt machte — die Show übernahm also einen bestehenden Ausdruck, statt einen zu prägen.", "en": "환불 (refund) + 메이크업. The root phrase 환불원정대 came first: per Namuwiki it circulated in women-majority online communities around 2008–2009, riffing on the Fellowship of the Ring, for people who look like any shop would refund them on sight. In 2020 the MBC variety show Hangout with Yoo borrowed the name for its project girl group, which is what made it nationally famous — the show took an existing phrase rather than coining one.", "es": "환불 (reembolso) + 메이크업. La expresión raíz 환불원정대 es anterior: según Namuwiki circulaba hacia 2008-2009 en comunidades mayoritariamente femeninas, jugando con la Comunidad del Anillo, para gente a la que cualquier tienda devolvería el dinero solo con verla. En 2020 el programa de MBC Hangout with Yoo tomó prestado el nombre para su grupo de chicas, y eso fue lo que lo hizo famoso en todo el país: el programa tomó una expresión existente, no la creó.", "ja": "「환불(返金)」+「메이크업」。元になった表現「환불원정대(返金遠征隊)」の方が先で、ナムウィキによれば2008~2009年頃、女性中心のコミュニティで『指輪の仲間(반지원정대)』をもじり、「この人たちが抗議すればどの店でも返金してくれそう」という意味で使われていた。2020年MBC『遊んで何するの?』のプロジェクトガールグループがこの名を借りたことで全国区の言葉になった——つまりバラエティが言葉を作ったのではなく、既にあった言葉を借りた側である。", "vi": "환불 (hoàn tiền) + 메이크업. Cụm gốc 환불원정대 có trước: theo Namuwiki, nó lưu hành trong các cộng đồng mạng đa số nữ khoảng 2008–2009, nhại lại Đoàn hộ Nhẫn, để chỉ những người mà cửa hàng nào nhìn thấy cũng sẽ hoàn tiền ngay. Năm 2020, chương trình MBC Hangout with Yoo mượn tên này đặt cho nhóm nhạc nữ dự án, và đó là lúc nó nổi tiếng toàn quốc — tức là chương trình mượn cụm từ có sẵn chứ không sáng tạo ra nó."}'::jsonb, '''환불메이크업 하고 갔다'', ''오늘 화장 좀 센데? 환불메이크업이야?''처럼 쓴다. 띄어쓰기(''환불 메이크업'')나 ''센언니 메이크업''으로 써도 같은 말이고, 어느 쪽으로 검색해도 항목 하나다. 놀리는 말이 아니라 ''오늘 각오하고 나왔구나'' 하는 느낌의 가벼운 농담으로 쓴다. 다만 강한 화장을 한 사람에게 함부로 붙이면 화가 나 보인다는 뜻으로 오해될 수 있어, 보통 본인이 스스로 말하는 쪽이 자연스럽다.', '{"de": "Verwendet als 환불메이크업 하고 갔다 (ich bin mit Rückerstattungs-Make-up hingegangen), 오늘 화장 좀 센데? 환불메이크업이야? (heute ziemlich stark geschminkt — Rückerstattungs-Make-up?). Mit Leerzeichen (환불 메이크업) oder als 센언니 메이크업 ist es dasselbe Wort, und jede Suche führt auf diesen einen Eintrag. Es ist leichtes Necken im Sinne von ''du bist heute offenbar vorbereitet'', kein Spott. Jemandem das nur wegen kräftigen Make-ups anzuhängen kann allerdings so klingen, als nenne man sie wütend — daher passt es besser über sich selbst.", "en": "Used as 환불메이크업 하고 갔다 (I went in with refund makeup on), 오늘 화장 좀 센데? 환불메이크업이야? (strong look today — is that refund makeup?). Spacing it (환불 메이크업) or saying 센언니 메이크업 gives the same word, and either search lands on this one entry. It is light teasing, closer to ''I see you came ready'', not mockery. Still, pinning it on someone just because their makeup is bold can read as calling them angry, so it sits more naturally as something you say about yourself.", "es": "Se usa como 환불메이크업 하고 갔다 (fui con el maquillaje de reembolso puesto), 오늘 화장 좀 센데? 환불메이크업이야? (hoy vas fuerte, ¿es maquillaje de reembolso?). Separarlo (환불 메이크업) o decir 센언니 메이크업 es la misma palabra, y cualquier búsqueda lleva a esta única entrada. Es una broma ligera, del tipo ''ya veo que vienes preparada'', no una burla. Aun así, soltárselo a alguien solo porque lleva un maquillaje marcado puede sonar a que la llamas enfadada, así que encaja mejor dicho de una misma.", "ja": "「환불메이크업 하고 갔다(強めメイクで行った)」「오늘 화장 좀 센데? 환불메이크업이야?(今日メイク強くない?)」のように使う。分かち書き(환불 메이크업)でも「센언니 메이크업」でも同じ語で、どちらで検索しても項目は一つ。からかいではなく「今日は気合入れてきたね」くらいの軽い冗談。ただ濃いメイクの人に軽々しく言うと「怒っているように見える」という意味に取られかねないので、自分について言う方が自然。", "vi": "Dùng kiểu 환불메이크업 하고 갔다 (mình đi với lớp makeup ''đòi hoàn tiền''), 오늘 화장 좀 센데? 환불메이크업이야? (hôm nay makeup căng nhỉ, kiểu đòi hoàn tiền à?). Viết tách (환불 메이크업) hay nói 센언니 메이크업 đều là cùng một từ, tìm kiểu nào cũng ra đúng một mục. Đây là câu đùa nhẹ, kiểu ''thấy nay chuẩn bị tinh thần rồi ha'', không phải chê. Dù vậy, gán cho ai đó chỉ vì họ trang điểm đậm có thể bị hiểu là bảo họ trông đang giận, nên nói về chính mình thì tự nhiên hơn."}'::jsonb, array['꾸안꾸', '얼빡']::text[], array['환불 메이크업', '센언니 메이크업', '쎈언니 메이크업']::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Refund makeup (fierce, don''t-mess-with-me look)"}, {"lang": "🇯🇵 JA", "text": "返金メイク(強めメイク)"}, {"lang": "🇨🇳 ZH", "text": "退貨妝(氣場全開的濃妝)"}, {"lang": "🇻🇳 VI", "text": "Makeup ''đòi hoàn tiền'' (lối trang điểm sắc lạnh)"}, {"lang": "🇪🇸 ES", "text": "Maquillaje de reembolso (look imponente)"}, {"lang": "🇩🇪 DE", "text": "Rückerstattungs-Make-up (bestimmter Look)"}]'::jsonb),
('506', '하울', 'Ha-Ul', 'beauty', 'reels', '세일 때 쓸어 담기, 그리고 산 걸 펼쳐 보여주는 콘텐츠', '{"de": "Ein Haul — Großeinkauf und das Video, in dem man die Beute zeigt", "en": "A haul — bulk-buying, and the video showing off what you bought", "es": "Un haul: compra masiva y el vídeo donde enseñas lo comprado", "ja": "まとめ買い、そして買った物を並べて見せるコンテンツ", "vi": "Haul — mua sắm số lượng lớn và video khoe đồ vừa mua"}'::jsonb, '[하울]', '[{"type": "명사", "examples": [{"de": "Beim Olive-Young-Sale habe ich einen ordentlichen Haul gemacht.", "es": "Me hice un haul en condiciones durante las rebajas de Olive Young.", "ja": "オリーブヤングのセールでガッツリまとめ買いした。", "vi": "Đợt sale Olive Young mình đã haul một trận ra trò.", "eng": "I did a proper haul during the Olive Young sale.", "kor": "올리브영 세일 때 하울 제대로 했다."}, {"de": "Ich habe ein Haul-Video geschaut und hätte fast wieder alles gekauft.", "es": "Estaba viendo un vídeo de haul y casi vuelvo a comprarlo todo.", "ja": "ハウル動画見てたらまた買いそうになった。", "vi": "Đang xem video haul mà suýt nữa lại vung tiền.", "eng": "I was watching a haul video and nearly bought everything again.", "kor": "하울 영상 보다가 또 지를 뻔했어."}], "definition": "화장품 세일이나 이벤트 때 여러 개를 한꺼번에 쓸어 담듯 사는 일. 나아가 그렇게 산 물건들을 책상에 늘어놓고 하나씩 보여주며 이야기하는 영상·게시물 형식 자체를 가리키기도 한다. 뷰티 유튜브·숏폼의 대표 포맷이라 ''올영 하울'', ''다이소 하울''처럼 산 곳 이름을 앞에 붙여 쓴다.", "definition_i18n": {"de": "Bei einem Sale oder einer Aktion einen ganzen Stapel Kosmetik auf einmal kaufen. Im erweiterten Sinn bezeichnet es auch das Format selbst — das Video oder der Post, in dem man alles auf dem Tisch ausbreitet und Stück für Stück durchgeht. Es ist ein Standardformat auf Beauty-YouTube und im Kurzvideo, daher steht der Ladenname davor: 올영 하울 (Olive-Young-Haul), 다이소 하울 (Daiso-Haul).", "en": "Buying a pile of cosmetics at once during a sale or promotion. By extension it also names the format itself — the video or post where you lay everything out on a desk and go through it piece by piece. It is a staple of beauty YouTube and short-form, so the shop name goes in front: 올영 하울 (Olive Young haul), 다이소 하울 (Daiso haul).", "es": "Comprar un montón de cosméticos de golpe en una rebaja o promoción. Por extensión nombra también el formato en sí: el vídeo o post donde lo extiendes todo sobre la mesa y lo repasas pieza por pieza. Es un clásico del YouTube de belleza y del formato corto, así que el nombre de la tienda va delante: 올영 하울 (haul de Olive Young), 다이소 하울 (haul de Daiso).", "ja": "化粧品のセールやイベントで一度に大量に買い込むこと。さらに、そうして買った物を机に並べて一つずつ見せながら話す動画・投稿の形式そのものも指す。ビューティー系YouTubeやショート動画の定番フォーマットなので、「올영 하울」「다이소 하울」のように買った店名を前に付けて使う。", "vi": "Việc mua một lô mỹ phẩm cùng lúc trong đợt sale hoặc khuyến mãi. Rộng hơn, nó còn chỉ chính cái định dạng nội dung — video hay bài đăng mà bạn bày hết đồ ra bàn rồi giới thiệu từng món. Đây là format quen thuộc của YouTube làm đẹp và video ngắn, nên tên cửa hàng được đặt phía trước: 올영 하울 (haul Olive Young), 다이소 하울 (haul Daiso)."}}]'::jsonb, '영어 haul(끌어모은 것, 수확물)을 그대로 들여온 말. 영미권 유튜브의 haul video 포맷이 2010년대 한국 뷰티 유튜브로 옮겨오면서 굳었다. 다만 뜻풀이는 출처마다 갈린다 — ''몽땅 쓸어 담다/대량 구매''로 보는 쪽(인사이트, 보그)이 다수이고, ''득템하다''에 가깝게 푸는 쪽(마리끌레르)도 있다. 어느 쪽이 먼저인지는 확정되지 않았다.', '{"de": "Eine direkte Entlehnung des englischen ''haul'' (die Ausbeute, die Ladung). Das Haul-Video-Format des englischsprachigen YouTube trug es in den 2010ern ins koreanische Beauty-YouTube, wo es blieb. Die Quellen sind sich bei der Bedeutung allerdings uneins: die meisten (Insight, Vogue Korea) lesen es als Großeinkauf oder Alles-Abräumen, Marie Claire Korea dagegen näher an 득템 (einen Glücksgriff machen). Welcher Sinn zuerst da war, ist ungeklärt.", "en": "A straight borrowing of English ''haul'' (the take, the load). The Anglophone YouTube haul-video format carried it into Korean beauty YouTube in the 2010s, where it stuck. Sources do differ on the gloss, though: most (Insight, Vogue Korea) read it as bulk-buying or sweeping everything up, while Marie Claire Korea reads it closer to 득템 (scoring a great find). Which sense came first is not settled.", "es": "Préstamo directo del inglés ''haul'' (el botín, la carga). El formato del haul video del YouTube anglosajón lo trajo al YouTube de belleza coreano en la década de 2010, donde cuajó. Eso sí, las fuentes discrepan en la glosa: la mayoría (Insight, Vogue Korea) lo leen como compra masiva o arrasar con todo, mientras que Marie Claire Korea lo acerca a 득템 (dar con un chollo). Cuál sentido vino primero no está resuelto.", "ja": "英語 haul(かき集めたもの、収穫)をそのまま取り入れた語。英語圏YouTubeのhaul動画という形式が2010年代に韓国のビューティーYouTubeへ移って定着した。ただし語釈は出典で割れる——「まとめ買い/根こそぎ買う」とするもの(インサイト、VOGUE KOREA)が多数だが、「득템(掘り出し物を手に入れる)」に近く解するもの(マリ・クレール韓国)もある。どちらが先かは確定していない。", "vi": "Vay mượn thẳng từ tiếng Anh ''haul'' (chiến lợi phẩm, mẻ hàng). Định dạng haul video của YouTube nói tiếng Anh đã đưa nó vào YouTube làm đẹp Hàn Quốc những năm 2010 và trụ lại. Tuy vậy các nguồn không thống nhất cách giải nghĩa: phần lớn (Insight, Vogue Korea) hiểu là mua số lượng lớn, vơ hết; còn Marie Claire Korea lại hiểu gần với 득템 (vớ được món hời). Nghĩa nào có trước thì chưa ngã ngũ."}'::jsonb, '''하울했다'', ''하울 영상'', ''올영 하울''처럼 쓴다. 산 곳 이름을 앞에 붙이는 게 기본이고, 아무 수식 없이 ''하울''만 쓰면 보통 영상 포맷을 가리킨다. 돈을 많이 썼다는 뉘앙스가 깔려 있어서 자랑과 자책이 반반 섞인 톤으로 쓰는 일이 많다.', '{"de": "Verwendet als 하울했다 (ich habe einen Haul gemacht), 하울 영상 (Haul-Video), 올영 하울 (Olive-Young-Haul). Üblicherweise steht der Ladenname davor; bloßes 하울 meint meist das Videoformat. Es schwingt mit, dass man viel ausgegeben hat, daher klingt es oft halb nach Angeberei, halb nach Reue.", "en": "Used as 하울했다 (I did a haul), 하울 영상 (haul video), 올영 하울 (Olive Young haul). Fronting the shop name is the default; bare 하울 usually means the video format. It carries an undertone of having spent a lot, so people often use it in a tone that is half boast, half regret.", "es": "Se usa como 하울했다 (me hice un haul), 하울 영상 (vídeo de haul), 올영 하울 (haul de Olive Young). Lo normal es anteponer el nombre de la tienda; 하울 a secas suele referirse al formato de vídeo. Lleva implícito que te has gastado bastante, así que se usa a menudo en un tono mitad presumido, mitad arrepentido.", "ja": "「하울했다(まとめ買いした)」「하울 영상(ハウル動画)」「올영 하울」のように使う。買った店名を前に付けるのが基本で、何も付けずに「하울」だけなら普通は動画フォーマットを指す。お金を使ったという含みがあるので、自慢と後悔が半々のトーンで使われることが多い。", "vi": "Dùng kiểu 하울했다 (mình đã haul), 하울 영상 (video haul), 올영 하울 (haul Olive Young). Mặc định là đặt tên cửa hàng lên trước; nếu chỉ nói trống không 하울 thì thường là chỉ định dạng video. Từ này ngầm mang ý đã tiêu khá nhiều tiền, nên người ta hay dùng với giọng nửa khoe nửa tiếc."}'::jsonb, array['플렉스']::text[], null, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Haul (shopping haul / haul video)"}, {"lang": "🇯🇵 JA", "text": "ハウル(まとめ買い)"}, {"lang": "🇨🇳 ZH", "text": "掃貨 / 開箱分享"}, {"lang": "🇻🇳 VI", "text": "Haul (mua sắm số lượng lớn)"}, {"lang": "🇪🇸 ES", "text": "Haul (compra masiva)"}, {"lang": "🇩🇪 DE", "text": "Haul (Großeinkauf)"}]'::jsonb),
('507', '화떡', 'Hwa-Tteok', 'beauty', null, '화장을 너무 두껍게 한 상태를 비꼬는 말', '{"de": "Spott für viel zu dick aufgetragenes Make-up", "en": "A jab at makeup caked on way too thick", "es": "Pulla para el maquillaje puesto a paletadas", "ja": "化粧が厚塗りすぎる状態を皮肉る語", "vi": "Lời châm chọc lớp trang điểm dày cộm"}'::jsonb, '[화떡]', '[{"type": "명사", "examples": [{"de": "Unter dem Licht sehe ich, dass ich es heute viel zu dick aufgetragen habe.", "es": "Con esta luz veo que hoy me lo he puesto a paletadas.", "ja": "照明の下で見たら今日完全に厚塗りだわ。", "vi": "Đứng dưới đèn mới thấy hôm nay mình trát dày quá.", "eng": "Under this light I can see I caked it on way too hard today.", "kor": "조명 밑에서 보니까 나 오늘 완전 화떡이네."}, {"de": "Als ich anfing zu schwitzen, sah alles verklumpt aus, also hab ich es abgenommen.", "es": "En cuanto empecé a sudar se notó todo apelmazado, así que me lo quité.", "ja": "汗かいたら厚塗り感が出てきたから全部落とした。", "vi": "Đổ mồ hôi cái là thấy trát dày lộ hết, nên mình tẩy luôn.", "eng": "Once I started sweating it looked all caked, so I just took it off.", "kor": "땀나니까 화떡 티 나서 그냥 지웠어."}], "definition": "화장을 지나치게 두껍게 한 상태. 표준어 ''떡칠''(풀이나 페인트처럼 덕지덕지 바르는 일)에서 온 말로, 파운데이션이 뭉치거나 각질이 일어나 화장한 티가 과하게 나는 얼굴을 가리킨다. 두께 자체보다 ''떡처럼 발라 놨다''는 조롱이 핵심이라 중립적인 말이 아니다.", "definition_i18n": {"de": "Ein Gesicht mit viel zu dick aufgetragenem Make-up. Es kommt von 떡칠, dem Standardwort fürs pappige Draufschmieren, und zielt auf Foundation, die fleckig wird oder an trockenen Schüppchen hängt. Der Stachel liegt im Bild — ''wie Reiskuchen draufgespachtelt'' — also nie eine neutrale Beschreibung.", "en": "A face with makeup piled on far too thick. It comes from 떡칠, the standard word for slapping something on in gluey layers, and points at foundation that has gone patchy or clung to dry flakes. The sting is in the image — ''troweled on like rice cake'' — so it is never a neutral description.", "es": "Una cara con el maquillaje amontonado a lo bestia. Viene de 떡칠, la palabra estándar para embadurnar en capas pegajosas, y apunta a la base que se ha cuarteado o se ha agarrado a la piel seca. El veneno está en la imagen —''untado como pasta de arroz''—, así que nunca es una descripción neutra.", "ja": "化粧を厚く塗りすぎた状態。標準語「떡칠(のりやペンキのようにべたべた塗ること)」から来た語で、ファンデがよれたり角質が浮いて化粧感が出すぎた顔を指す。厚さそのものより「餅のように塗りたくった」という嘲りが核心なので、中立的な表現ではない。", "vi": "Khuôn mặt bị trát trang điểm quá dày. Từ này đến từ 떡칠, từ chuẩn chỉ việc bôi trét thành từng lớp dính nhớp, ám chỉ lớp nền bị mốc hoặc bám vào da bong. Cái cay nằm ở hình ảnh — ''trát như bánh gạo'' — nên đây không bao giờ là lời mô tả trung tính."}}]'::jsonb, '''화장''의 ''화''와 ''떡칠''의 ''떡''을 붙여 줄인 말. 어근인 ''떡칠''은 표준국어대사전에도 올라 있는 말이지만, 줄임 형태 ''화떡''과 그 비꼬는 쓰임은 사전에 없다. 언제부터 쓰였는지는 확인된 출처가 없어 특정하지 않는다.', '{"de": "Gebildet aus 화 von 화장 (Make-up) und 떡 von 떡칠 (draufschmieren). Die Wurzel 떡칠 steht im Standardwörterbuch, die Kurzform 화떡 und ihr spöttischer Gebrauch nicht. Keine Quelle nennt den Beginn, daher kein Datum.", "en": "Formed by gluing 화 from 화장 (makeup) to 떡 from 떡칠 (slathering on). The root 떡칠 is in the Standard Korean Dictionary, but the clipped 화떡 and its mocking use are not. No source records when it started, so no date is claimed.", "es": "Se forma pegando 화 de 화장 (maquillaje) a 떡 de 떡칠 (embadurnar). La raíz 떡칠 está en el Diccionario Estándar, pero el recorte 화떡 y su uso burlón no. Ninguna fuente registra cuándo empezó, así que no se afirma fecha.", "ja": "「화장(化粧)」の「화」と「떡칠」の「떡」を合わせた略語。語根の「떡칠」は標準国語大辞典にあるが、略形「화떡」とその皮肉な用法は載っていない。いつからかを示す出典はなく特定しない。", "vi": "Ghép 화 trong 화장 (trang điểm) với 떡 trong 떡칠 (trát bôi). Gốc 떡칠 có trong Từ điển Chuẩn, còn dạng rút gọn 화떡 và cách dùng giễu cợt thì không. Không nguồn nào ghi thời điểm bắt đầu nên không nêu mốc."}'::jsonb, '남의 얼굴에 대고 쓰면 그대로 외모 비하가 된다. 실제로는 거울이나 사진을 보고 ''나 오늘 화떡했네''처럼 자기 화장을 두고 자조할 때 가장 많이 쓴다.', '{"de": "Auf jemand anderen gemünzt ist es eine direkte Beleidigung des Aussehens. In der Praxis nutzt man es meist über sich selbst — beim Blick in Spiegel oder Foto: 나 오늘 화떡했네 (heute hab ich es echt dick aufgetragen).", "en": "Aimed at someone else it is a straight insult about their looks. In practice it is used most on yourself — catching your reflection or a photo and going 나 오늘 화떡했네 (I really caked it on today).", "es": "Dirigido a otra persona es un insulto directo sobre su aspecto. En la práctica se usa sobre todo con uno mismo, al verse en el espejo o en una foto: 나 오늘 화떡했네 (hoy me lo he puesto a paletadas).", "ja": "他人の顔に向けて使えばそのまま容姿の貶しになる。実際は鏡や写真を見て「今日厚塗りしちゃったな」と自分の化粧を自嘲するときに最も多く使う。", "vi": "Nói vào mặt người khác thì thành lời chê ngoại hình thẳng thừng. Thực tế nó hay được dùng cho chính mình nhất — soi gương hay xem ảnh rồi thốt lên 나 오늘 화떡했네 (hôm nay mình trát dày thật)."}'::jsonb, array['마기꾼']::text[], array['화장떡칠']::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Caked-on makeup"}, {"lang": "🇯🇵 JA", "text": "化粧の厚塗り"}, {"lang": "🇨🇳 ZH", "text": "妆太厚(糊了一脸)"}, {"lang": "🇻🇳 VI", "text": "Trang điểm trát dày"}, {"lang": "🇪🇸 ES", "text": "Maquillaje a paletadas"}, {"lang": "🇩🇪 DE", "text": "Dick aufgetragenes Make-up"}]'::jsonb),
('508', '퍼컬', 'Peo-Keol', 'beauty', null, '나한테 어울리는 색을 찾아주는 ''퍼스널 컬러''의 줄임말', '{"de": "Kurzform von ''Personal Color'' — die Farbpalette, die dir steht", "en": "Short for ''personal color'' — the palette that suits you", "es": "Abreviatura de ''color personal'': la paleta que te favorece", "ja": "自分に似合う色を診断する「パーソナルカラー」の略", "vi": "Viết tắt của ''personal color'' — bảng màu hợp với bạn"}'::jsonb, '[퍼컬]', '[{"type": "명사", "examples": [{"de": "Meine Personal Color ist Sommer kühl rausgekommen, deshalb geht dieser Lippenstift nicht.", "es": "Mi color personal salió verano frío, así que este labial no me sirve.", "ja": "私、パーソナルカラー夏クールだった。だからこのリップ無理。", "vi": "Màu cá nhân của mình ra hè lạnh, nên son này chịu thôi.", "eng": "My personal color came out summer cool, so I can''t wear this lipstick.", "kor": "나 퍼컬 여름쿨 나왔어. 그래서 이 립 못 써."}, {"de": "Seit der Farbberatung fällt mir Klamottenkaufen viel leichter.", "es": "Comprar ropa se volvió mucho más fácil después del análisis de color.", "ja": "パーソナルカラー診断してから服買うのがずっと楽になった。", "vi": "Từ hồi đi soi màu cá nhân, mua quần áo dễ hơn hẳn.", "eng": "Buying clothes got way easier after I got my colors done.", "kor": "퍼컬 받고 나서 옷 사는 게 훨씬 쉬워졌어."}], "definition": "피부·머리카락·눈동자 색을 기준으로 자기한테 가장 잘 어울리는 색 계열을 찾아내는 진단, 또는 그렇게 진단받은 자기 색 유형. 보통 봄웜·여름쿨·가을웜·겨울쿨 네 계절로 나누고, 라이트·브라이트·뮤트·딥처럼 더 잘게 쪼개기도 한다. 한국에서는 돈을 내고 진단을 받은 뒤 그 결과대로 화장품·옷·염색 색을 고르는 것이 하나의 소비 문화가 됐다.", "definition_i18n": {"de": "Die Analyse, welche Farbfamilie zu Haut, Haar und Augen passt — oder der Typ, den man dabei zugewiesen bekommt. Sie teilt in vier Jahreszeiten (Frühling warm, Sommer kühl, Herbst warm, Winter kühl) und oft in feinere Töne wie hell, klar, gedämpft und tief. In Korea ist es eine eigene Konsumkultur geworden, eine Beratung zu bezahlen und danach Make-up, Kleidung und Haarfarbe auszuwählen.", "en": "The diagnosis that works out which color family suits you based on your skin, hair and eye color — or the type you end up with. It splits into four seasons (spring warm, summer cool, autumn warm, winter cool) and often into finer tones like light, bright, muted and deep. In Korea, paying for a consultation and then buying makeup, clothes and hair dye by the result has become its own consumer culture.", "es": "El diagnóstico que determina qué familia de colores te favorece según tu piel, cabello y ojos, o el tipo que te asignan. Se divide en cuatro estaciones (primavera cálida, verano fría, otoño cálida, invierno fría) y a menudo en tonos más finos: claro, brillante, apagado, profundo. En Corea, pagar por una consulta y luego comprar maquillaje, ropa y tinte según el resultado se ha vuelto toda una cultura de consumo.", "ja": "肌・髪・瞳の色をもとに自分に最も似合う色の系統を割り出す診断、またはその結果としての自分のタイプ。春ウォーム・夏クール・秋ウォーム・冬クールの四季に分け、さらにライト・ブライト・ミュート・ディープなど細かく分けることも多い。韓国では有料診断を受け、その結果どおりにコスメ・服・ヘアカラーを選ぶことが一つの消費文化になっている。", "vi": "Việc chẩn đoán xem nhóm màu nào hợp với bạn dựa trên màu da, tóc và mắt — hoặc chính kiểu màu bạn được xếp vào. Chia thành bốn mùa (xuân ấm, hè lạnh, thu ấm, đông lạnh) và thường chia nhỏ hơn thành sáng, tươi, trầm, sâu. Ở Hàn, trả tiền đi soi màu rồi mua mỹ phẩm, quần áo, thuốc nhuộm theo kết quả đã thành hẳn một văn hoá tiêu dùng."}}]'::jsonb, '영어 personal color를 줄인 말. 색채 진단 이론 자체는 바깥에서 들어왔지만, ''퍼컬''이라는 줄임말과 4계절 × 세부 톤 체계를 유료 진단 산업으로 키운 것은 2010년대 후반 한국 뷰티 커뮤니티다. 누가 처음 줄여 썼는지는 출처마다 없어 특정하지 않는다.', '{"de": "Kurzform des englischen ''personal color''. Die Farbanalyse-Theorie kam von außen, doch die Kurzform und das System aus vier Jahreszeiten mit Untertönen wuchs in koreanischen Beauty-Communities Ende der 2010er zu einer kostenpflichtigen Diagnosebranche. Keine Quelle nennt den Urheber der Kurzform.", "en": "A clipping of English ''personal color''. The color-analysis theory itself came from abroad, but the clipped form and the four-season-by-sub-tone system grew into a paid diagnosis industry in Korean beauty communities in the late 2010s. No source names who first shortened it.", "es": "Recorte del inglés ''personal color''. La teoría del análisis del color vino de fuera, pero la forma abreviada y el sistema de cuatro estaciones con subtonos se convirtió en una industria de diagnóstico de pago en las comunidades de belleza coreanas a finales de la década de 2010. Ninguna fuente dice quién lo abrevió primero.", "ja": "英語 personal color の略。色彩診断の理論自体は外から入ったが、「퍼컬」という略語と四季×細分トーンの体系を有料診断産業に育てたのは2010年代後半の韓国のビューティーコミュニティ。誰が最初に略したかは出典になく特定しない。", "vi": "Rút gọn từ tiếng Anh ''personal color''. Lý thuyết soi màu đến từ nước ngoài, nhưng dạng rút gọn và hệ bốn mùa kèm tông phụ đã thành cả một ngành soi màu trả phí trong cộng đồng làm đẹp Hàn cuối thập niên 2010. Không nguồn nào nói ai rút gọn đầu tiên."}'::jsonb, '''퍼컬 받았어(진단받았어)'', ''퍼컬 뭐야?'', ''이 립 내 퍼컬 아니야''처럼 쓴다. 진단 결과를 MBTI처럼 자기소개에 붙이는 사람도 많다. 어느 쪽으로 검색해도 항목 하나 — 줄이지 않은 ''퍼스널컬러''도 같은 말이다.', '{"de": "Verwendet als 퍼컬 받았어 (ich habe eine Beratung gemacht), 퍼컬 뭐야? (welcher Typ bist du?), 이 립 내 퍼컬 아니야 (dieser Lippenstift ist nicht mein Typ). Viele geben das Ergebnis in der Selbstvorstellung an, wie sonst den MBTI. Egal wie man sucht, es gibt nur diesen einen Eintrag — das ungekürzte 퍼스널컬러 ist dasselbe Wort.", "en": "Used as 퍼컬 받았어 (I got diagnosed), 퍼컬 뭐야? (what''s your color type?), 이 립 내 퍼컬 아니야 (this lipstick isn''t my type). Many people list the result in a self-intro the way they list an MBTI. Searching either form lands on this one entry — the unclipped 퍼스널컬러 is the same word.", "es": "Se usa como 퍼컬 받았어 (me hice el análisis), 퍼컬 뭐야? (¿cuál es tu tipo?), 이 립 내 퍼컬 아니야 (este labial no es de mi tipo). Mucha gente pone el resultado en su presentación como si fuera el MBTI. Busques como busques, es una sola entrada: 퍼스널컬러 sin recortar es la misma palabra.", "ja": "「퍼컬 받았어(診断を受けた)」「퍼컬 뭐야?(何タイプ?)」「이 립 내 퍼컬 아니야(このリップは私のタイプじゃない)」のように使う。MBTIのように自己紹介に結果を書く人も多い。どちらで検索しても項目は一つ——略さない「퍼스널컬러」も同じ語。", "vi": "Dùng kiểu 퍼컬 받았어 (mình đi soi màu rồi), 퍼컬 뭐야? (bạn tông gì?), 이 립 내 퍼컬 아니야 (son này không hợp tông mình). Nhiều người ghi kết quả vào phần giới thiệu bản thân như ghi MBTI. Tìm kiểu nào cũng ra đúng một mục — 퍼스널컬러 dạng đầy đủ là cùng một từ."}'::jsonb, array['추구미', '꾸안꾸']::text[], array['퍼스널컬러', '퍼스널 컬러']::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Personal color (seasonal color analysis)"}, {"lang": "🇯🇵 JA", "text": "パーソナルカラー(略語)"}, {"lang": "🇨🇳 ZH", "text": "个人色彩诊断"}, {"lang": "🇻🇳 VI", "text": "Màu cá nhân (soi tông màu)"}, {"lang": "🇪🇸 ES", "text": "Color personal (análisis estacional)"}, {"lang": "🇩🇪 DE", "text": "Personal Color / Farbtyp"}]'::jsonb),
('509', '팩토', 'Paek-To', 'beauty', null, '팩처럼 올려두고 쓰는 토너 — ''팩 + 토너''', '{"de": "Toner wie eine Maske aufgelegt — ''Pack + Toner''", "en": "Toner used like a mask, left on the skin — ''pack + toner''", "es": "Tónico usado como mascarilla, dejándolo sobre la piel: ''pack + tóner''", "ja": "パックのように乗せて使う化粧水——「パック+トナー」", "vi": "Toner dùng như mặt nạ, đắp lên da — ''pack + toner''"}'::jsonb, '[팩토]', '[{"type": "명사", "examples": [{"de": "Meine Haut ist heute ausgerastet, also habe ich vor dem Schlafen Toner-Pads aufgelegt.", "es": "Hoy se me descontroló la piel, así que me puse discos de tónico antes de dormir.", "ja": "今日肌荒れひどくて、パックトナーして寝た。", "vi": "Hôm nay da mình nổi loạn nên đắp toner rồi mới ngủ.", "eng": "My skin freaked out today so I did a toner-pad mask before bed.", "kor": "오늘 피부 뒤집어져서 팩토 하고 잤어."}, {"de": "Ein Pad macht Maske und Abwischen zugleich — voll der Gewinn.", "es": "Con un solo disco haces mascarilla y limpieza a la vez: un chollo.", "ja": "パッド一枚でパックトナーも拭き取りもできるから超お得。", "vi": "Một miếng pad làm được cả đắp lẫn lau, lời quá trời.", "eng": "One pad does both the mask soak and the wipe-off — total win.", "kor": "패드 한 장으로 팩토랑 닦토 같이 되니까 개이득."}], "definition": "토너를 화장솜이나 패드에 충분히 적셔서 얼굴에 3~5분쯤 올려두는 사용법. 마스크팩을 대신하는 간이 팩이라 ''팩 + 토너''로 부른다. 같은 토너라도 쓰는 방식에 따라 이름이 갈리는데, 닦아내면 닦토, 두드려 흡수시키면 흡토, 올려두면 팩토다. 건조하거나 자극받은 부위에만 부분적으로 얹는 식으로도 많이 쓴다.", "definition_i18n": {"de": "Ein Wattepad mit Toner tränken und drei bis fünf Minuten auf dem Gesicht liegen lassen. Es ersetzt eine Tuchmaske, daher 팩 (Pack) + 토너 (Toner). Derselbe Toner bekommt je nach Anwendung einen anderen Namen: abwischen ist 닦토, einklopfen ist 흡토, liegen lassen ist 팩토. Viele nutzen es auch punktuell und legen Pads nur auf trockene oder gereizte Stellen.", "en": "Soaking a cotton pad in toner and leaving it on the face for three to five minutes. It stands in for a sheet mask, hence 팩 (pack) + 토너 (toner). The same toner gets a different name depending on how you use it: wipe it off and it is 닦토, pat it in and it is 흡토, leave it sitting and it is 팩토. People also use it spot-wise, laying pads only on dry or irritated areas.", "es": "Empapar un disco de algodón en tónico y dejarlo sobre el rostro unos tres a cinco minutos. Sustituye a una mascarilla de tela, de ahí 팩 (pack) + 토너 (tónico). El mismo tónico cambia de nombre según cómo se use: si lo retiras es 닦토, si lo das a golpecitos es 흡토, si lo dejas puesto es 팩토. También se usa por zonas, colocando discos solo en las partes secas o irritadas.", "ja": "化粧水をコットンやパッドにたっぷり含ませ、顔に3~5分ほど乗せておく使い方。シートマスクの代わりになる簡易パックなので「팩(パック)+토너」と呼ぶ。同じ化粧水でも使い方で名前が変わり、拭き取れば닦토、叩いて浸透させれば흡토、乗せておけば팩토となる。乾燥した部分や荒れた部分だけに部分的に乗せる使い方も多い。", "vi": "Thấm đẫm toner vào bông tẩy trang rồi đắp lên mặt khoảng ba đến năm phút. Nó thay cho mặt nạ giấy, nên gọi là 팩 (pack) + 토너. Cùng một lọ toner nhưng tên gọi đổi theo cách dùng: lau đi là 닦토, vỗ cho thấm là 흡토, để yên trên da là 팩토. Người ta cũng hay dùng theo vùng, chỉ đắp lên chỗ khô hoặc đang kích ứng."}}]'::jsonb, '''팩''과 ''토너''를 각각 한 글자씩 따서 붙인 줄임말. 같은 토너를 쓰는 방식이 여러 갈래로 나뉘면서 닦토(닦는 토너)·흡토(흡수시키는 토너)와 구분하려고 생긴 이름이다. 셋 중 어느 말이 먼저 생겼는지, 누가 처음 썼는지는 출처에 없어 특정하지 않는다.', '{"de": "Eine Kurzform aus je einer Silbe von 팩 (Pack) und 토너 (Toner). Sie entstand, um diese Anwendung von 닦토 (abwischen) und 흡토 (einklopfen) abzugrenzen, als sich die Tonerverwendung in mehrere Stile aufteilte. Keine Quelle sagt, welches der drei zuerst da war oder wer sie prägte.", "en": "A clipping that takes one syllable each from 팩 (pack) and 토너 (toner). It arose to distinguish this use from 닦토 (wipe-off toner) and 흡토 (patted-in toner) once toner use split into several styles. No source says which of the three came first or who coined them.", "es": "Un recorte que toma una sílaba de 팩 (pack) y otra de 토너 (tónico). Surgió para distinguir este uso de 닦토 (tónico de retirar) y 흡토 (tónico de dar golpecitos) cuando el uso del tónico se dividió en varios estilos. Ninguna fuente dice cuál de los tres es anterior ni quién los acuñó.", "ja": "「팩(パック)」と「토너(トナー)」から一字ずつ取った略語。同じ化粧水の使い方が幾つにも分かれる中で、닦토(拭き取り)・흡토(浸透)と区別するために生まれた呼び名。三つのうちどれが先か、誰が最初に使ったかは出典になく特定しない。", "vi": "Một dạng rút gọn lấy mỗi từ một âm tiết: 팩 (pack) và 토너 (toner). Nó ra đời để phân biệt với 닦토 (toner lau) và 흡토 (toner vỗ thấm) khi cách dùng toner tách thành nhiều kiểu. Không nguồn nào nói trong ba từ thì từ nào có trước hay ai đặt ra chúng."}'::jsonb, '''팩토 한다'', ''이거 팩토용으로 좋아''처럼 쓴다. 닦토·흡토와 한 세트라 셋을 비교하는 맥락에서 같이 나오는 일이 많다. 제품 이름이 아니라 쓰는 방법을 가리키는 말이라, 아무 토너나 팩토로 쓸 수 있다.', '{"de": "Verwendet als 팩토 한다 (ich mache eine Toner-Pad-Maske), 이거 팩토용으로 좋아 (der eignet sich gut dafür). Es gehört als Set zu 닦토 und 흡토, daher kommen die drei beim Vergleichen oft gemeinsam vor. Es benennt eine Methode, keine Produktart — jeder Toner lässt sich so verwenden.", "en": "Used as 팩토 한다 (I do a toner-pad mask), 이거 팩토용으로 좋아 (this one is good for pad-masking). It travels as a set with 닦토 and 흡토, so the three often come up together in comparisons. It names a method, not a product type — any toner can be used this way.", "es": "Se usa como 팩토 한다 (me hago una mascarilla de tónico), 이거 팩토용으로 좋아 (este va bien para eso). Va en conjunto con 닦토 y 흡토, así que los tres suelen salir juntos al compararlos. Nombra un método, no un tipo de producto: cualquier tónico sirve.", "ja": "「팩토 한다(パックトナーする)」「이거 팩토용으로 좋아(これはパックトナー向き)」のように使う。닦토・흡토と一組なので、三つを比べる文脈で一緒に出てくることが多い。製品名ではなく使い方を指す語なので、どんな化粧水でも팩토として使える。", "vi": "Dùng kiểu 팩토 한다 (mình đắp toner), 이거 팩토용으로 좋아 (lọ này đắp hợp lắm). Nó đi thành bộ với 닦토 và 흡토 nên cả ba hay được nhắc cùng nhau khi so sánh. Từ này chỉ cách dùng chứ không phải loại sản phẩm — toner nào cũng đắp kiểu này được."}'::jsonb, array['닦토', '흡토']::text[], null, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Pack-toner (toner-soaked pad mask)"}, {"lang": "🇯🇵 JA", "text": "パックトナー(コットンパック)"}, {"lang": "🇨🇳 ZH", "text": "化妝水濕敷"}, {"lang": "🇻🇳 VI", "text": "Đắp toner (toner pad mask)"}, {"lang": "🇪🇸 ES", "text": "Tónico en mascarilla (discos empapados)"}, {"lang": "🇩🇪 DE", "text": "Toner-Pad-Maske"}]'::jsonb),
('510', '파데', 'Pa-De', 'beauty', null, '''파운데이션''을 줄인 말', '{"de": "Kurzform von ''Foundation''", "en": "Clipped form of ''foundation''", "es": "Forma abreviada de ''base de maquillaje''", "ja": "「ファンデーション」の略", "vi": "Dạng rút gọn của ''kem nền''"}'::jsonb, '[파데]', '[{"type": "명사", "examples": [{"de": "Endlich meine Holy-Grail-Foundation gefunden — die setzt sich wirklich nicht ab.", "es": "Por fin encontré mi base definitiva: esta de verdad no se cuartea.", "ja": "人生ファンデやっと見つけた。これは本当に浮かない。", "vi": "Cuối cùng cũng tìm được kem nền chân ái, cái này thật sự không bị mốc.", "eng": "I finally found my holy-grail foundation — this one really doesn''t cake.", "kor": "인생 파데 드디어 찾았어. 이건 진짜 안 뜬다."}, {"de": "Ich war spät dran und bin ohne Foundation rausgegangen.", "es": "Iba con prisa y salí sin base.", "ja": "今日急いでたからファンデ塗らずに出てきた。", "vi": "Hôm nay vội quá nên mình ra ngoài không đánh nền luôn.", "eng": "I was in a rush so I came out without any foundation.", "kor": "오늘 급해서 파데 안 바르고 그냥 나왔어."}], "definition": "파운데이션의 줄임말. 피부톤을 고르게 덮어 잡티와 붉은 기를 가려 주는 베이스 화장품을 가리킨다. 한국에서는 단독으로도 쓰지만 ''인생 파데(나한테 완벽하게 맞는 파운데이션)'', ''파데 프리(파운데이션을 아예 안 바르는 화장)''처럼 붙여 쓰는 말이 더 흔하다.", "definition_i18n": {"de": "Kurz für Foundation, das Basisprodukt, das den Hautton ausgleicht und Unreinheiten und Rötungen abdeckt. Es steht allein, häufiger aber in Zusammensetzungen: 인생 파데 (die Holy-Grail-Foundation, die endlich passt) und 파데 프리 (ein Look ganz ohne Foundation).", "en": "Short for foundation, the base product that evens out skin tone and covers blemishes and redness. It stands alone, but shows up even more often inside compounds: 인생 파데 (the holy-grail foundation that finally matches you) and 파데 프리 (a foundation-free look).", "es": "Abreviatura de base de maquillaje, el producto que unifica el tono y tapa manchas y rojeces. Se usa sola, pero aún más en compuestos: 인생 파데 (la base definitiva que por fin te queda) y 파데 프리 (un look sin base).", "ja": "ファンデーションの略。肌のトーンを均一にし、シミや赤みを覆うベースメイク製品を指す。単独でも使うが、「인생 파데(自分に完璧に合う人生ファンデ)」「파데 프리(ファンデを塗らないメイク)」のような複合語での使用がさらに多い。", "vi": "Rút gọn của kem nền, sản phẩm nền giúp đều màu da và che khuyết điểm, vết đỏ. Dùng riêng được, nhưng hay gặp hơn trong cụm: 인생 파데 (kem nền chân ái cuối cùng cũng hợp) và 파데 프리 (lớp trang điểm không dùng kem nền)."}}]'::jsonb, '''파운데이션''의 첫 음절 ''파''와 셋째 음절 ''데''를 따서 줄인 말. 뷰티 커뮤니티와 매장에서 입말로 굳은 표현이라 언제부터 쓰였는지는 어느 출처에도 없고, 최근에는 기사 제목에도 설명 없이 쓰인다.', '{"de": "Gebildet aus der ersten und dritten Silbe von 파운데이션. Es verfestigte sich als mündliche Kurzform in Beauty-Communities und an Kosmetiktheken; keine Quelle hält den Beginn fest, heute steht es sogar unerklärt in Schlagzeilen.", "en": "Built from the first and third syllables of 파운데이션 (pa-un-de-i-syeon). It hardened as spoken shorthand in beauty communities and cosmetics counters; no source records when it started, and it now appears unglossed even in news headlines.", "es": "Formada con la primera y la tercera sílaba de 파운데이션. Cuajó como abreviatura hablada en comunidades de belleza y mostradores de cosmética; ninguna fuente registra cuándo empezó y hoy aparece sin glosar hasta en titulares.", "ja": "「파운데이션」の第1音節「파」と第3音節「데」を取った略語。ビューティーコミュニティや店頭の話し言葉として定着したもので、いつからかを記した出典はなく、最近は記事の見出しにも説明なしで使われる。", "vi": "Ghép âm tiết thứ nhất và thứ ba của 파운데이션. Nó đọng lại như cách nói tắt trong cộng đồng làm đẹp và quầy mỹ phẩm; không nguồn nào ghi lại thời điểm bắt đầu, và giờ xuất hiện thẳng cả trên tiêu đề báo."}'::jsonb, '화장품 이야기에서는 ''파운데이션''보다 ''파데''가 훨씬 자주 나온다. 어느 쪽으로 검색해도 항목 하나 — ''파운데이션''과 같은 말이다. ''쿠션''(스펀지에 적신 형태)과는 제형이 달라 보통 구분해서 부른다.', '{"de": "Im Make-up-Gespräch fällt 파데 weit öfter als das volle 파운데이션. Egal wie man sucht, es gibt nur diesen Eintrag — dasselbe Wort. 쿠션 (Cushion, die schwammgetränkte Form) wird wegen der anderen Textur meist getrennt benannt.", "en": "In makeup talk 파데 turns up far more often than the full 파운데이션. Searching either form lands on this one entry — they are the same word. 쿠션 (cushion, the sponge-soaked format) is usually named separately because the texture differs.", "es": "Al hablar de maquillaje aparece mucho más 파데 que el completo 파운데이션. Busques como busques es una sola entrada: son la misma palabra. El 쿠션 (cushion, formato de esponja) se nombra aparte porque la textura es distinta.", "ja": "コスメの話では「파운데이션」より「파데」のほうがはるかに多く出る。どちらで検索しても項目は一つ——同じ語。「쿠션(クッション:スポンジ含浸タイプ)」はテクスチャーが違うので普通は別扱い。", "vi": "Khi nói chuyện trang điểm, 파데 xuất hiện nhiều hơn hẳn dạng đầy đủ 파운데이션. Tìm kiểu nào cũng ra một mục — cùng một từ. Còn 쿠션 (cushion, dạng thấm bông) thường được gọi riêng vì chất khác."}'::jsonb, array['화떡']::text[], array['파운데이션']::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Foundation (clipped)"}, {"lang": "🇯🇵 JA", "text": "ファンデ(ファンデーションの略)"}, {"lang": "🇨🇳 ZH", "text": "粉底(简称)"}, {"lang": "🇻🇳 VI", "text": "Kem nền (nói tắt)"}, {"lang": "🇪🇸 ES", "text": "Base de maquillaje (abreviado)"}, {"lang": "🇩🇪 DE", "text": "Foundation (Kurzform)"}]'::jsonb),
('511', '톤그로', 'Ton-Geu-Ro', 'beauty', null, '안 어울리는 색을 써서 얼굴이 칙칙해 보이는 상태', '{"de": "Töne tragen, die mit dem eigenen Hautton kollidieren", "en": "Wearing shades that clash with your skin tone", "es": "Llevar tonos que chocan con tu piel", "ja": "似合わない色を使って顔がくすんで見える状態", "vi": "Dùng tông màu chỏi với da khiến mặt xỉn"}'::jsonb, '[톤그로]', '[{"type": "명사", "examples": [{"de": "Mit diesem Cushion bin ich voll Tone-Aggro — Gesicht und Hals haben andere Farben.", "es": "Con este cushion voy full tone-aggro: la cara y el cuello no pegan.", "ja": "このクッション塗ると完全にトングロ。首と色が違いすぎる。", "vi": "Đánh cushion này là mình tông chỏi luôn, mặt với cổ hai màu khác nhau.", "eng": "This cushion makes me total tone-aggro — my face and neck are different colors.", "kor": "나 이 쿠션 바르면 완전 톤그로야. 목이랑 색이 따로 놀아."}, {"de": "Bevor ich meinen Farbtyp kannte, lief ich voll Tone-Aggro herum, jetzt nicht mehr.", "es": "Antes de saber mi color personal iba en plan tone-aggro total, ya no.", "ja": "パーソナルカラー知らなかった頃は本当にトングロで歩いてたけど、今は違う。", "vi": "Hồi chưa biết màu cá nhân mình đi làm tông chỏi thật sự, giờ thì hết rồi.", "eng": "Before I knew my color type I walked around fully tone-aggro, but not anymore.", "kor": "퍼컬 모를 땐 진짜 톤그로로 다녔는데 지금은 안 그래."}], "definition": "자기 피부톤이나 퍼스널 컬러에 맞지 않는 색을 써서 얼굴이 칙칙하거나 붕 떠 보이는 상태, 또는 그런 사람. 파운데이션 색이 피부보다 밝거나 어두워 목과 얼굴 경계가 드러나는 경우에 특히 자주 쓴다. ''톤(tone)''에 게임·커뮤니티 용어 ''어그로(괜히 시선과 반감을 끄는 행동)''를 붙인 말이라, ''색으로 어그로를 끈다''는 비꼬는 뉘앙스가 깔려 있다.", "definition_i18n": {"de": "Farben tragen, die mit dem eigenen Hautton oder Farbtyp kollidieren, sodass das Gesicht fahl wirkt oder sich vom Hals absetzt — oder die Person, die das tut. Am häufigsten, wenn die Foundation heller oder dunkler als die Haut ist und am Kiefer eine Kante sichtbar wird. Das Wort klebt ''Tone'' an ''Aggro'' (Gaming- und Forenslang für Aufmerksamkeit und Ärger erzeugen) und hat damit einen spöttischen Unterton: die Farbwahl sucht Streit.", "en": "Wearing colors that clash with your skin tone or personal color, so your face looks dull or floats off your neck — or the person doing it. It comes up most often when a foundation is lighter or darker than the skin and the jawline shows a visible border. The word glues ''tone'' to ''aggro'' (gaming and forum slang for drawing attention and irritation), so it carries a teasing edge: your color choice is picking a fight.", "es": "Llevar colores que chocan con tu tono de piel o tu color personal, de modo que la cara se ve apagada o desencajada del cuello — o la persona que lo hace. Sale sobre todo cuando la base es más clara u oscura que la piel y se marca el borde en la mandíbula. La palabra pega ''tono'' a ''aggro'' (jerga de juegos y foros para atraer atención y fastidio), así que lleva una pulla: tu elección de color está buscando bronca.", "ja": "自分の肌トーンやパーソナルカラーに合わない色を使い、顔がくすんだり浮いて見える状態、またはそういう人。ファンデの色が肌より明るい・暗いせいで首との境目が出るときに特によく使う。「トーン」にゲーム・コミュニティ用語の「アグロ(無駄に注目と反感を集める行為)」を付けた語なので、色でアグロを稼いでいるという皮肉が効いている。", "vi": "Dùng màu chỏi với tông da hay màu cá nhân của mình, khiến mặt xỉn hoặc trôi khỏi cổ — hoặc chính người làm vậy. Hay gặp nhất khi kem nền sáng hay tối hơn da, để lộ đường ranh ở quai hàm. Từ này ghép ''tone'' với ''aggro'' (tiếng lóng game và diễn đàn, nghĩa là hút sự chú ý và bực bội), nên mang giọng châm chọc: màu bạn chọn đang gây sự."}}]'::jsonb, '''톤(tone)''에 게임·커뮤니티 용어 ''어그로(aggro)''를 붙인 조어. 퍼스널 컬러 유행과 함께 뷰티 커뮤니티에서 퍼졌고, 지금은 화장품 기사에서도 설명 없이 그대로 쓸 만큼 굳었다. 처음 쓰인 시기나 최초 사용자를 밝힌 출처는 없어 특정하지 않는다.', '{"de": "Eine Mischung aus ''Tone'' und ''Aggro'', dem Gaming- und Forenbegriff fürs Provozieren von Aufmerksamkeit. Es verbreitete sich mit dem Personal-Color-Boom in Beauty-Communities und steht heute selbst in Kosmetiknews ohne Erklärung. Keine Quelle nennt Anfangszeit oder Urheber.", "en": "A blend of ''tone'' and ''aggro'', the gaming and forum term for provoking attention. It spread through beauty communities alongside the personal-color boom and is now used unglossed even in cosmetics news. No source pins down when it started or who coined it.", "es": "Mezcla de ''tono'' y ''aggro'', el término de videojuegos y foros para provocar atención. Se extendió por las comunidades de belleza junto al auge del color personal y hoy aparece sin glosar incluso en noticias de cosmética. Ninguna fuente fija cuándo empezó ni quién lo acuñó.", "ja": "「トーン」とゲーム・コミュニティ用語「アグロ」を合わせた造語。パーソナルカラー流行とともにビューティーコミュニティで広まり、今では化粧品記事でも説明なしに使われるほど定着した。初出時期や造語者を示す出典はなく特定しない。", "vi": "Ghép ''tone'' với ''aggro'', từ trong game và diễn đàn chỉ việc khiêu khích gây chú ý. Nó lan trong cộng đồng làm đẹp cùng cơn sốt màu cá nhân, giờ báo mỹ phẩm dùng thẳng không cần giải thích. Không nguồn nào xác định thời điểm hay người đặt ra."}'::jsonb, '자기 얘기로 쓰면 자조지만, 남의 화장을 두고 ''톤그로다''라고 하면 외모 평가라 실례가 된다. ''나 톤그로야'', ''이 색은 톤그로 나''처럼 자기 자신이나 제품을 주어로 쓰는 게 안전하다.', '{"de": "Auf sich selbst bezogen ist es Selbstironie, über fremdes Make-up gesagt ist es ein Aussehensurteil und kommt schlecht an. Besser sich selbst oder das Produkt zum Subjekt machen: 나 톤그로야 (ich bin Tone-Aggro), 이 색은 톤그로 나 (dieser Ton wird bei mir Tone-Aggro).", "en": "Self-applied it is self-deprecating, but calling someone else''s makeup 톤그로 is an appearance judgment and lands badly. Keep yourself or the product as the subject: 나 톤그로야 (I''m tone-aggro), 이 색은 톤그로 나 (this shade goes tone-aggro on me).", "es": "Aplicado a uno mismo es autoironía, pero decirlo del maquillaje ajeno es juzgar el aspecto y queda fatal. Mejor que el sujeto seas tú o el producto: 나 톤그로야 (soy tone-aggro), 이 색은 톤그로 나 (este tono me queda tone-aggro).", "ja": "自分に使えば自虐だが、他人の化粧を指して言うと外見評価になり失礼。「나 톤그로야(私はトングロ)」「이 색은 톤그로 나(この色はトングロになる)」のように自分か製品を主語にするのが無難。", "vi": "Tự nói về mình thì là tự giễu, nhưng chê lớp trang điểm của người khác là 톤그로 thì thành phán xét ngoại hình, rất mất lịch sự. Nên để chủ ngữ là bản thân hoặc sản phẩm: 나 톤그로야 (mình tông chỏi), 이 색은 톤그로 나 (màu này lên mình bị chỏi)."}'::jsonb, array['퍼컬', '톤망진창', '마기꾼']::text[], null, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Wearing shades that clash with your skin tone"}, {"lang": "🇯🇵 JA", "text": "似合わない色で顔がくすむこと"}, {"lang": "🇨🇳 ZH", "text": "用了不衬肤色的颜色"}, {"lang": "🇻🇳 VI", "text": "Dùng tông màu chỏi với da"}, {"lang": "🇪🇸 ES", "text": "Llevar tonos que no te favorecen"}, {"lang": "🇩🇪 DE", "text": "Farben, die dem Hautton widersprechen"}]'::jsonb),
('512', '코덕', 'Ko-Deok', 'beauty', null, '화장품에 미쳐 있는 사람 — ''코스메틱 덕후''의 줄임말', '{"de": "Kurzform von ''Cosmetic-덕후'' — jemand, der von Kosmetik besessen ist", "en": "Short for ''cosmetics 덕후'' — a makeup obsessive", "es": "Abreviatura de ''cosmetic 덕후'': un obsesionado con el maquillaje", "ja": "「コスメオタク」の略——化粧品にハマっている人", "vi": "Viết tắt của ''cosmetic 덕후'' — người nghiện mỹ phẩm"}'::jsonb, '[코덕]', '[{"type": "명사", "examples": [{"de": "Sie ist ein totaler Kosmetik-Nerd — allein über dreißig Lippenstifte.", "es": "Ella es una friki del maquillaje total: solo de labiales tiene más de treinta.", "ja": "あの子ガチのコスメオタクだよ。リップだけで30本超え。", "vi": "Nhỏ đó là dân nghiện mỹ phẩm chính hiệu. Riêng son thôi đã hơn ba chục cây.", "eng": "She''s a total makeup nerd — she''s got over thirty lipsticks alone.", "kor": "쟤 완전 코덕이야. 립만 서른 개 넘어."}, {"de": "Ich habe vorher meine Kosmetik-Nerd-Freundin gefragt — echt eine gute Entscheidung.", "es": "Le pregunté a mi amiga friki del maquillaje antes de comprarlo y la verdad, acerté.", "ja": "コスメオタクの友達に聞いてから買ったけど、マジで正解だった。", "vi": "Mình hỏi đứa bạn nghiện mỹ phẩm rồi mới mua, công nhận chọn chuẩn thật.", "eng": "I asked my makeup-nerd friend before buying it, and honestly, great call.", "kor": "코덕 친구한테 물어보고 샀는데 진짜 잘 샀어."}], "definition": "화장품을 쓰는 데서 그치지 않고, 신제품이 나오면 바로 사고 성분과 발색을 하나하나 비교하며 파고드는 사람. 영어 cosmetic의 ''코''와, 일본어 오타쿠에서 온 ''덕후''를 붙인 말이다. 비하가 아니라 스스로 ''나 코덕이야''라고 밝히는 정체성 표현에 가깝고, 화장품 리뷰·커뮤니티에서는 신뢰의 표시로도 통한다.", "definition_i18n": {"de": "Jemand, der Kosmetik nicht nur benutzt, sondern sich hineinstürzt — jede Neuheit kauft, Inhaltsstofflisten und Swatches einzeln vergleicht. Es verbindet 코 von englisch ''cosmetic'' mit 덕후, der koreanischen Form von japanisch otaku. Es ist keine Beleidigung: Man nennt sich selbst 코덕, und in Reviews und Communities gilt es als Zeichen von Glaubwürdigkeit.", "en": "Someone who does not just use makeup but dives into it — buying every new release, comparing ingredient lists and swatches one by one. It joins 코 from English ''cosmetic'' with 덕후, the Korean form of Japanese otaku. It is not an insult: people call themselves 코덕, and in review and community spaces it reads as a badge of credibility.", "es": "Alguien que no solo usa maquillaje, sino que se sumerge en él: compra cada lanzamiento, compara listas de ingredientes y swatches uno por uno. Une el 코 de ''cosmetic'' con 덕후, la forma coreana del japonés otaku. No es un insulto: la gente se autodenomina 코덕, y en reseñas y comunidades funciona como sello de credibilidad.", "ja": "化粧品を使うだけでなく、新製品が出れば即買い、成分や発色を一つずつ比べて掘り下げる人。英語 cosmetic の「코」と、日本語のオタク由来の「덕후」を合わせた語。侮蔑ではなく「私コスメオタクなの」と自ら名乗るアイデンティティ表現に近く、レビューやコミュニティでは信頼の証としても通じる。", "vi": "Người không chỉ dùng mỹ phẩm mà còn đào sâu vào nó — mua mọi sản phẩm mới ra, so sánh từng bảng thành phần và từng vệt swatch. Từ này ghép 코 của ''cosmetic'' với 덕후, dạng tiếng Hàn của otaku Nhật. Đây không phải lời chê: người ta tự nhận mình là 코덕, và trong giới review hay cộng đồng thì nó được coi là dấu hiệu đáng tin."}}]'::jsonb, '영어 cosmetic의 첫 음절 ''코'' + ''덕후''. ''덕후''는 일본어 오타쿠(おたく)가 한국에서 ''오덕후''를 거쳐 줄어든 말이다. 무엇에 깊이 빠진 사람에게 ''-덕''을 붙이는 한국식 조어(입덕·탈덕·홈마 계열)가 화장품 쪽으로 옮겨온 경우다. 누가 언제 처음 썼는지는 출처에 없어 특정하지 않는다.', '{"de": "코, die erste Silbe des englischen ''cosmetic'', plus 덕후 — koreanisch für einen besessenen Fan, selbst eine Kurzform von 오덕후, aus japanisch otaku. Es ist die koreanische Gewohnheit, -덕 an das anzuhängen, worin jemand tief steckt (vgl. 입덕, 탈덕), hier auf Make-up angewandt. Keine Quelle hält fest, wer es zuerst benutzte.", "en": "코, the first syllable of English ''cosmetic'', plus 덕후 — Korean for an obsessive fan, itself a clipping of 오덕후, from Japanese otaku. It is the Korean habit of tacking -덕 onto whatever someone is deep into (compare 입덕, 탈덕), applied to makeup. No source records who used it first or when.", "es": "코, primera sílaba del inglés ''cosmetic'', más 덕후, palabra coreana para un fan obsesivo, a su vez recorte de 오덕후, del japonés otaku. Es la costumbre coreana de añadir -덕 a aquello en lo que alguien está metido (compárese 입덕, 탈덕), aplicada al maquillaje. Ninguna fuente registra quién lo usó primero ni cuándo.", "ja": "英語 cosmetic の頭音節「코」+「덕후」。「덕후」は日本語のオタクが韓国で「오덕후」を経て縮まった語。何かに深くハマった人に「-덕」を付ける韓国式の造語法(입덕・탈덕の系統)が化粧品に及んだ例。誰がいつ最初に使ったかは出典になく特定しない。", "vi": "코, âm tiết đầu của ''cosmetic'' trong tiếng Anh, cộng với 덕후 — từ tiếng Hàn chỉ người hâm mộ cuồng nhiệt, vốn rút gọn từ 오덕후, bắt nguồn từ otaku tiếng Nhật. Đây là thói quen tiếng Hàn gắn -덕 vào thứ mà ai đó đam mê (so với 입덕, 탈덕), nay áp vào mỹ phẩm. Không nguồn nào ghi lại ai dùng đầu tiên và khi nào."}'::jsonb, '''나 코덕이야'', ''코덕력 대단하다'', ''코덕 친구''처럼 쓴다. 자기 소개로도 남을 가리킬 때도 쓰고, 둘 다 나쁜 뜻이 없다. 화장을 잘한다는 말이 아니라 화장품을 많이 안다는 말이라, 제품 추천을 부탁할 때 자연스럽게 따라붙는 호칭이다. 립 제품만 파면 ''립덕''으로 더 좁혀 부른다.', '{"de": "Verwendet als 나 코덕이야 (ich bin ein Kosmetik-Nerd), 코덕력 대단하다 (dein Kosmetikwissen ist krass), 코덕 친구 (meine Kosmetik-Nerd-Freundin). Funktioniert für einen selbst wie für andere, in beiden Fällen ohne negativen Beiklang. Es heißt, dass man Produkte kennt, nicht dass man gut schminkt — daher fällt es natürlich, wenn man um Empfehlungen bittet. Für jemanden, der nur bei Lippenprodukten tief einsteigt, verengt man es zu 립덕.", "en": "Used as 나 코덕이야 (I''m a makeup nerd), 코덕력 대단하다 (your makeup-nerd knowledge is serious), 코덕 친구 (my makeup-nerd friend). Works both as a self-description and for others, with no negative edge either way. It says you know products, not that you apply them well, so it comes up naturally when asking for recommendations. Narrow it to 립덕 for someone who only goes deep on lip products.", "es": "Se usa como 나 코덕이야 (soy friki del maquillaje), 코덕력 대단하다 (tu nivel de friki es serio), 코덕 친구 (mi amiga friki del maquillaje). Sirve tanto para describirse a uno mismo como a otros, sin carga negativa. Dice que sabes de productos, no que los apliques bien, así que surge de forma natural al pedir recomendaciones. Para quien solo profundiza en labiales, se afina a 립덕.", "ja": "「나 코덕이야(私コスメオタク)」「코덕력 대단하다(コスメ知識すごい)」「코덕 친구(コスメオタクの友達)」のように使う。自己紹介にも他人を指すのにも使い、どちらも悪い意味はない。メイクが上手いではなく化粧品に詳しいという意味なので、製品を薦めてもらう場面で自然に付く呼び名。リップだけ極めるなら「립덕」とより狭く呼ぶ。", "vi": "Dùng kiểu 나 코덕이야 (mình là dân nghiện mỹ phẩm), 코덕력 대단하다 (kiến thức mỹ phẩm của bạn đỉnh thật), 코덕 친구 (đứa bạn nghiện mỹ phẩm). Dùng được cho cả bản thân lẫn người khác, đều không mang nghĩa xấu. Nó nói bạn rành sản phẩm chứ không phải bạn trang điểm đẹp, nên hay xuất hiện khi ai đó xin gợi ý mua đồ. Nếu chỉ chuyên về son thì gọi hẹp hơn là 립덕."}'::jsonb, array['하울', '덕질']::text[], array['코스메틱 덕후']::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Makeup nerd / cosmetics otaku"}, {"lang": "🇯🇵 JA", "text": "コスメオタク"}, {"lang": "🇨🇳 ZH", "text": "美妝控 / 化妝品宅"}, {"lang": "🇻🇳 VI", "text": "Dân nghiện mỹ phẩm"}, {"lang": "🇪🇸 ES", "text": "Friki del maquillaje"}, {"lang": "🇩🇪 DE", "text": "Kosmetik-Nerd"}]'::jsonb),
('513', '저속노화', 'Jeo-Song-No-Hwa', 'beauty', 'daily', '노화를 막는 대신 천천히 늙는 쪽을 택하는 관리 방식', '{"de": "Langsam altern statt Altern zu stoppen", "en": "Aiming to age slowly rather than not at all", "es": "Envejecer despacio en vez de intentar no envejecer", "ja": "老化を止めるのではなくゆっくり老いることを選ぶ管理法", "vi": "Chọn lão hoá chậm thay vì cố chống lão hoá"}'::jsonb, '[저송노화]', '[{"type": "명사", "examples": [{"de": "Ich mache neuerdings dieses Slow-Aging — weniger weißer Reis und wirklich täglich Sonnencreme.", "es": "Últimamente voy con lo del slow aging: menos arroz blanco y protector solar todos los días.", "ja": "最近スローエイジングするって白米減らして日焼け止めもちゃんと塗ってる。", "vi": "Dạo này mình theo lão hoá chậm nên giảm cơm trắng và bôi kem chống nắng đều đặn.", "eng": "I''m doing the slow-aging thing lately — cutting white rice and actually wearing sunscreen every day.", "kor": "요즘 저속노화 한다고 흰쌀 줄이고 선크림도 꼬박꼬박 발라."}, {"de": "Diese Ampulle kam mit Slow-Aging-Konzept raus, nicht als Anti-Aging.", "es": "Esta ampolla salió con concepto de slow aging, no de antiaging.", "ja": "このアンプル、アンチエイジングじゃなくてスローエイジングのコンセプトで出てた。", "vi": "Cái ampoule này ra mắt theo concept lão hoá chậm chứ không phải chống lão hoá.", "eng": "This ampoule is marketed as slow-aging rather than anti-aging.", "kor": "이 앰플 안티에이징 말고 저속노화 콘셉트로 나왔더라."}], "definition": "노화를 막거나 되돌리는 게 아니라 진행 속도를 늦추는 데 초점을 둔 관리 방식. 혈당이 급하게 오르지 않는 식단, 충분한 수면과 규칙적인 운동, 자외선 차단과 피부 장벽 관리까지 한 묶음으로 부른다. 겉모습을 빨리 되돌리려는 ''안티에이징''과 대비되는 말로 자리 잡아서, 화장품 마케팅에서도 안티에이징 대신 이 말을 내세우는 경우가 늘었다.", "definition_i18n": {"de": "Eine Pflegephilosophie, die das Tempo des Alterns bremsen will, statt es zu stoppen oder umzukehren. Sie bündelt eine Ernährung ohne Blutzuckerspitzen, genug Schlaf und regelmäßige Bewegung sowie Sonnenschutz und Hautbarrierepflege. Sie hat sich als Gegengewicht zum Anti-Aging etabliert, das ein schnelles Zurückdrehen des Aussehens verspricht, und die Kosmetikwerbung stellt zunehmend dieses Wort voran.", "en": "A care philosophy aimed at slowing the pace of aging rather than blocking or reversing it. It bundles eating that keeps blood sugar from spiking, enough sleep and regular exercise, plus sun protection and skin-barrier care. It has settled in as the counterweight to anti-aging — which chases a fast rollback of appearance — and cosmetics marketing increasingly leads with this word instead.", "es": "Una filosofía de cuidado centrada en frenar el ritmo del envejecimiento, no en detenerlo ni revertirlo. Agrupa una alimentación que evita los picos de azúcar, dormir lo suficiente y hacer ejercicio con regularidad, más protección solar y cuidado de la barrera cutánea. Se ha asentado como contrapeso del antiaging —que persigue revertir rápido el aspecto— y el marketing cosmético cada vez usa más esta palabra en su lugar.", "ja": "老化を止めたり巻き戻したりするのではなく、進む速度を落とすことに重点を置く管理法。血糖が急激に上がらない食事、十分な睡眠と規則的な運動、日焼け止めと肌バリアのケアまでをひとまとめに呼ぶ。見た目を早く戻そうとする「アンチエイジング」と対になる語として定着し、化粧品のマーケティングでもアンチエイジングに代えてこの語を前面に出すことが増えた。", "vi": "Một triết lý chăm sóc hướng tới làm chậm tốc độ lão hoá chứ không chặn hay đảo ngược nó. Nó gộp chung chế độ ăn không gây tăng vọt đường huyết, ngủ đủ và tập đều, cùng với chống nắng và chăm sóc hàng rào da. Nó đã đứng vững như đối trọng của anti-aging — vốn theo đuổi việc kéo lùi ngoại hình thật nhanh — và marketing mỹ phẩm ngày càng dùng từ này thay thế."}}]'::jsonb, '노년내과 진료 현장에서 쓰이던 임상 개념이 2023~2024년 SNS·유튜브를 타고 대중어가 됐다. 2025년에는 배달 앱 메뉴 이름과 화장품 마케팅에까지 붙어 그 해의 트렌드 키워드로 꼽혔다. 특정 의사가 만들어 퍼뜨렸다는 설명이 여럿 돌지만 출처마다 이름과 시점이 달라 여기서는 개인을 특정하지 않는다.', '{"de": "Ein klinisches Konzept aus der Altersmedizin, das 2023-2024 über Social Media und YouTube zur Alltagssprache wurde. 2025 hing es an Menünamen von Lieferapps und an Kosmetikwerbung und wurde zum Trendwort des Jahres gekürt. Mehrere Darstellungen schreiben die Prägung einem bestimmten Arzt zu, doch Name und Zeitpunkt unterscheiden sich je nach Quelle — daher wird hier niemand genannt.", "en": "A clinical concept from geriatric medicine that became everyday language through social media and YouTube in 2023-2024. By 2025 it was attached to delivery-app menu names and cosmetics marketing and was picked as a trend keyword of the year. Several accounts credit a particular doctor with coining and spreading it, but the name and the date differ by source, so no individual is named here.", "es": "Un concepto clínico de la geriatría que se volvió lenguaje cotidiano a través de las redes y YouTube en 2023-2024. En 2025 ya se pegaba a nombres de menús de apps de reparto y al marketing cosmético, y fue elegido palabra clave de tendencia del año. Varias versiones atribuyen el término a cierto médico, pero el nombre y la fecha varían según la fuente, así que aquí no se señala a nadie.", "ja": "老年内科の臨床で使われていた概念が2023〜2024年にSNS・YouTubeを通じて一般語になった。2025年にはデリバリーアプリのメニュー名や化粧品マーケティングにまで付き、その年のトレンドキーワードに選ばれた。特定の医師が広めたという説明が複数あるが、出典によって名前も時期も異なるためここでは個人を特定しない。", "vi": "Một khái niệm lâm sàng trong lão khoa đã thành ngôn ngữ đời thường qua mạng xã hội và YouTube giai đoạn 2023-2024. Đến 2025 nó được gắn vào cả tên món trên app giao đồ ăn lẫn marketing mỹ phẩm và được chọn là từ khoá xu hướng của năm. Nhiều lời kể quy công cho một bác sĩ cụ thể, nhưng tên và mốc thời gian khác nhau tuỳ nguồn nên ở đây không nêu cá nhân nào."}'::jsonb, '''저속노화 식단'', ''저속노화 루틴'', ''저속노화템''처럼 앞에 붙여 쓴다. 영어로는 slow aging. 원래 식단·건강 쪽에서 더 많이 쓰이지만, 뷰티에서는 주름·탄력 제품이 ''안티에이징'' 대신 내세우는 말이 됐다. 띄어 써서 ''저속 노화''로 적기도 한다.', '{"de": "Es steht vor dem Substantiv: 저속노화 식단 (Slow-Aging-Ernährung), 저속노화 루틴 (Routine), 저속노화템 (Slow-Aging-Produkt). Auf Englisch heißt es Slow Aging. Am häufigsten fällt es in Ernährungs- und Gesundheitsgesprächen, in der Beauty ist es das, was Falten- und Straffungsprodukte statt Anti-Aging ausloben. Man schreibt es auch getrennt: 저속 노화.", "en": "It goes in front of a noun: 저속노화 식단 (slow-aging diet), 저속노화 루틴 (routine), 저속노화템 (slow-aging item). English calls it slow aging. It is heard most in food and health talk, but in beauty it has become the phrase wrinkle and firmness products use instead of anti-aging. It is also written spaced, 저속 노화.", "es": "Va delante del sustantivo: 저속노화 식단 (dieta slow aging), 저속노화 루틴 (rutina), 저속노화템 (producto slow aging). En inglés es slow aging. Se oye sobre todo en temas de alimentación y salud, pero en belleza se ha vuelto lo que los productos de arrugas y firmeza usan en lugar de antiaging. También se escribe separado, 저속 노화.", "ja": "「저속노화 식단(スローエイジング食)」「저속노화 루틴」「저속노화템」のように前に付けて使う。英語では slow aging。もともと食事・健康分野で使われることが多いが、ビューティーではシワ・ハリ製品が「アンチエイジング」に代えて掲げる語になった。分かち書きで「저속 노화」と書くこともある。", "vi": "Nó đứng trước danh từ: 저속노화 식단 (chế độ ăn lão hoá chậm), 저속노화 루틴 (routine), 저속노화템 (món đồ lão hoá chậm). Tiếng Anh gọi là slow aging. Nghe nhiều nhất trong chuyện ăn uống và sức khoẻ, nhưng trong làm đẹp nó đã thành cụm mà các sản phẩm chống nhăn, làm săn chắc dùng thay cho anti-aging. Cũng viết tách là 저속 노화."}'::jsonb, array['갓생', '오운완', '추구미']::text[], array['저속 노화']::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Slow aging"}, {"lang": "🇯🇵 JA", "text": "スローエイジング(低速老化)"}, {"lang": "🇨🇳 ZH", "text": "慢速衰老"}, {"lang": "🇻🇳 VI", "text": "Lão hoá chậm"}, {"lang": "🇪🇸 ES", "text": "Envejecimiento lento"}, {"lang": "🇩🇪 DE", "text": "Slow Aging"}]'::jsonb),
('514', '인생템', 'In-Saeng-Tem', 'beauty', 'daily', '평생 쓰고 싶을 만큼 나한테 딱 맞는 물건', '{"de": "Ein Holy-Grail-Produkt — das, was so gut passt, dass man es für immer behält", "en": "A holy-grail item — the one that fits you so well you''d keep it for life", "es": "Un imprescindible de por vida: el producto que te va tan bien que no lo cambias", "ja": "一生使いたいほど自分に合ったアイテム", "vi": "Món chân ái — thứ hợp đến mức muốn dùng cả đời"}'::jsonb, '[인생템]', '[{"type": "명사", "examples": [{"de": "Dieses Cushion ist mein Holy Grail — ich bin beim dritten.", "es": "Esta base en cojín es mi imprescindible de por vida; voy por la tercera.", "ja": "このクッション、マジで人生アイテム。今三個目。", "vi": "Cái cushion này đúng là chân ái. Mình đang mua cây thứ ba rồi.", "eng": "This cushion is my holy grail — I''m on my third one.", "kor": "이 쿠션 진짜 인생템이야. 세 개째 사는 중."}, {"de": "Alle nannten es Holy Grail, also habe ich es gekauft — bei mir war es nichts.", "es": "Lo compré porque decían que era un imprescindible, pero a mí no me fue bien.", "ja": "人生アイテムって言うから買ったけど、私にはイマイチだった。", "vi": "Nghe đồn là chân ái nên mình mua, mà với mình thì không hợp lắm.", "eng": "Everyone called it a holy grail so I bought it, but it didn''t work for me.", "kor": "인생템이라길래 샀는데 나한텐 별로였어."}], "definition": "''인생 아이템''의 줄임말. 한번 써 보고 ''이건 진짜다'' 싶어서 다 쓰면 또 사고, 남에게도 권하게 되는 물건. 단순히 좋은 제품이 아니라 ''나한테'' 맞았다는 개인적인 검증이 핵심이라, 남의 인생템이 내 인생템이 되지 않는 일도 흔하다. 화장품 얘기에서 특히 많이 쓰지만 물건이면 무엇에든 붙는다.", "definition_i18n": {"de": "Kurzform von 인생 아이템 (Lebens-Item). Das Ding, das man einmal probiert, bei dem man denkt ''das ist es'', das man nachkauft, sobald es leer ist, und weiterempfiehlt. Entscheidend ist nicht, dass es objektiv gut ist, sondern dass es sich persönlich für einen bewährt hat — deshalb floppt fremdes 인생템 bei einem selbst oft. Am häufigsten fällt es beim Thema Make-up, hängt sich aber an jedes Produkt.", "en": "Short for 인생 아이템 (life item). The thing you try once, think ''this is the one'', rebuy every time it runs out, and start recommending to others. The point is not that it is objectively good but that it was personally verified to suit you — so someone else''s 인생템 often flops on you. It comes up most in makeup talk but attaches to any product.", "es": "Abreviatura de 인생 아이템 (artículo de tu vida). Eso que pruebas una vez, piensas ''este es'', vuelves a comprar cada vez que se acaba y acabas recomendando. La clave no es que sea objetivamente bueno, sino que quedó verificado que te va a ti; por eso el 인생템 de otra persona a menudo te decepciona. Sale sobre todo hablando de maquillaje, pero se pega a cualquier producto.", "ja": "「인생 아이템(人生アイテム)」の略。一度使って「これは本物だ」と思い、使い切ればまた買い、人にも薦めるようになる物。単に良い製品というより「自分に」合ったという個人的な検証が核心なので、他人の인생템が自分には合わないこともよくある。化粧品の話で特によく使うが、物なら何にでも付く。", "vi": "Viết tắt của 인생 아이템 (món đồ của đời). Thứ bạn thử một lần, nghĩ ''đúng là nó rồi'', hết lại mua tiếp và bắt đầu giới thiệu cho người khác. Điểm mấu chốt không phải nó tốt một cách khách quan mà là nó đã được chính bạn kiểm chứng là hợp — nên 인생템 của người khác thường lại chẳng hợp với bạn. Từ này hay xuất hiện nhất trong chuyện mỹ phẩm nhưng gắn được với bất kỳ món đồ nào."}}]'::jsonb, '''인생''과 영어 item의 한국식 줄임꼴 ''템''을 붙인 말. 최고의 무엇을 가리킬 때 앞에 ''인생''을 붙이는 용법(인생 영화·인생 사진·인생 맛집)이 물건 쪽으로 확장된 경우다. 언제 누가 처음 썼는지는 출처에 나오지 않아 특정하지 않으며, 2016년 뷰티 매체의 신조어 정리 기사에는 이미 실려 있다.', '{"de": "인생 (Leben) plus 템, die koreanische Kurzform von englisch ''item''. Es überträgt auf Gegenstände die Gewohnheit, 인생 voranzustellen, um das Beste von etwas zu meinen (인생 영화 der Film deines Lebens, 인생 사진 das beste Foto von dir, 인생 맛집). Keine Quelle hält fest, wann oder von wem es zuerst benutzt wurde; in einer Neuwort-Übersicht eines Beauty-Magazins von 2016 steht es bereits.", "en": "인생 (life) plus 템, the Korean clipping of English ''item''. It extends to objects the habit of prefixing 인생 to mean the best of something (인생 영화 a life-changing film, 인생 사진 the best photo ever taken of you, 인생 맛집). No source records when or by whom it was first used; it already appears in a 2016 beauty-magazine neologism round-up.", "es": "인생 (vida) más 템, el recorte coreano del inglés ''item''. Extiende a los objetos la costumbre de anteponer 인생 para decir lo mejor de algo (인생 영화 la película de tu vida, 인생 사진 la mejor foto que te han hecho, 인생 맛집). Ninguna fuente registra cuándo ni quién lo usó primero; ya figura en un recopilatorio de neologismos de una revista de belleza de 2016.", "ja": "「인생(人生)」に英語 item の韓国式略形「템」を付けた語。最高の何かを指すのに「인생」を冠する用法(인생 영화・인생 사진・인생 맛집)が物へ広がった例。いつ誰が最初に使ったかは出典になく特定しない。2016年のビューティー誌の新語まとめ記事にはすでに載っている。", "vi": "인생 (đời) cộng với 템, dạng rút gọn kiểu Hàn của ''item'' tiếng Anh. Nó mở rộng sang đồ vật cái thói quen thêm 인생 phía trước để nói thứ tuyệt nhất (인생 영화 bộ phim của đời, 인생 사진 tấm ảnh đẹp nhất từng chụp, 인생 맛집). Không nguồn nào ghi lại ai dùng đầu tiên và khi nào; nó đã có trong bài tổng hợp từ mới của một tạp chí làm đẹp năm 2016."}'::jsonb, '''인생템이다'', ''인생 쿠션'', ''인생 파데''처럼 쓴다. 줄이지 않고 ''인생 아이템''이라 해도 같은 말이라 어느 쪽으로 검색해도 항목 하나다. 물건 이름 앞에 ''인생''만 붙여 쓰는 형태도 흔하다. 추천할 때 쓰는 최상급 표현이지만 어디까지나 개인 경험이라는 뜻이 깔려 있어서, ''내 인생템''처럼 소유격을 붙이면 더 정확하다. 비슷해 보이는 ''인템''은 ''인기 아이템''이라 뜻이 다르다.', '{"de": "Verwendet als 인생템이다 (das ist ein Holy Grail), 인생 쿠션, 인생 파데 (Holy-Grail-Cushion, -Foundation). Das ungekürzte 인생 아이템 ist dasselbe Wort, und jede Suche führt auf diesen einen Eintrag. Auch üblich: nur 인생 vor den Produktnamen setzen. Es ist die stärkste mögliche Empfehlung, trägt aber den Sinn einer persönlichen Erfahrung — 내 인생템 (mein Holy Grail) ist daher präziser. Das ähnlich aussehende 인템 ist etwas anderes: 인기 아이템, ein beliebter Artikel.", "en": "Used as 인생템이다 (it''s a holy grail), 인생 쿠션, 인생 파데 (holy-grail cushion, foundation). The unclipped 인생 아이템 is the same word, and either search lands on this one entry. Sticking just 인생 in front of a product name is also common. It is the strongest recommendation you can give, but it carries the sense of being one person''s experience, so 내 인생템 (my holy grail) is the more accurate phrasing. The similar-looking 인템 is different — that is 인기 아이템, a popular item.", "es": "Se usa como 인생템이다 (es un imprescindible), 인생 쿠션, 인생 파데 (la base o el cojín de tu vida). El 인생 아이템 sin recortar es la misma palabra, y cualquier búsqueda lleva a esta única entrada. También es común poner solo 인생 delante del nombre del producto. Es la recomendación más fuerte posible, pero lleva implícito que es la experiencia de una persona, así que 내 인생템 (mi imprescindible) es más preciso. El parecido 인템 es otra cosa: 인기 아이템, un artículo popular.", "ja": "「인생템이다(人生アイテムだ)」「인생 쿠션」「인생 파데」のように使う。略さない「인생 아이템」も同じ語で、どちらで検索しても項目は一つ。品名の前に「인생」だけ付ける形もよくある。薦めるときの最上級表現だが、あくまで個人の経験という含みがあるので「내 인생템(私の人生アイテム)」と所有格を付ける方が正確。似て見える「인템」は「인기 아이템(人気アイテム)」で意味が違う。", "vi": "Dùng kiểu 인생템이다 (đây là món chân ái), 인생 쿠션, 인생 파데 (cushion, kem nền chân ái). Dạng đầy đủ 인생 아이템 là cùng một từ, tìm kiểu nào cũng ra đúng một mục. Chỉ gắn 인생 trước tên sản phẩm cũng rất phổ biến. Đây là lời giới thiệu ở mức cao nhất, nhưng ngầm hiểu đó là trải nghiệm của riêng một người, nên nói 내 인생템 (chân ái của mình) thì chính xác hơn. Từ nhìn na ná là 인템 lại khác: đó là 인기 아이템, món đồ đang hot."}'::jsonb, array['하울', '코덕', '내돈내산']::text[], array['인생 아이템']::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Holy grail item / ride-or-die product"}, {"lang": "🇯🇵 JA", "text": "人生アイテム(神アイテム)"}, {"lang": "🇨🇳 ZH", "text": "人生單品 / 回購神物"}, {"lang": "🇻🇳 VI", "text": "Món chân ái"}, {"lang": "🇪🇸 ES", "text": "Imprescindible de por vida"}, {"lang": "🇩🇪 DE", "text": "Holy-Grail-Produkt"}]'::jsonb),
('515', '물광', 'Mul-Gwang', 'beauty', null, '물 머금은 듯 촉촉하게 빛나는 피부', '{"de": "Haut, die glänzt, als hielte sie Wasser", "en": "Skin that glows like it is holding water", "es": "Piel que brilla como si retuviera agua", "ja": "水分を含んだようにつやめく肌", "vi": "Làn da bóng căng như đang ngậm nước"}'::jsonb, '[물광]', '[{"type": "명사", "examples": [{"de": "Mit diesem Cushion kriegst du einen wahnsinnigen Dewy-Glow.", "es": "Con este cushion sale un brillo húmedo brutal.", "ja": "このクッション塗ると水光がやばいくらい出る。", "vi": "Đánh cushion này lên là da bóng căng khỏi bàn.", "eng": "This cushion gives you an insane dewy glow.", "kor": "이 쿠션 바르면 물광 장난 아니게 나와."}, {"de": "Vielleicht weil ich durchgeschlafen habe — mein Gesicht hat heute richtig Glow.", "es": "Será que dormí bien: hoy la cara me brilla de verdad.", "ja": "昨日ぐっすり寝たからか、今日は顔に水光が出てる。", "vi": "Chắc do tối qua ngủ đẫy giấc, hôm nay mặt mình bóng căng hẳn.", "eng": "Maybe it''s because I slept properly — my face has a real glow today.", "kor": "어제 푹 자서 그런가 오늘 얼굴에 물광 도네."}], "definition": "물을 머금은 듯 촉촉하게 빛나는 피부, 또는 그렇게 보이도록 연출하는 메이크업. 반짝이 입자로 낸 광이 아니라 ''속에서 수분이 차올라 비치는 광''처럼 보이는 것이 핵심이라, 발라서 만드는 동시에 피부 상태 자랑이기도 하다. K-뷰티의 대표 피부 표현으로 자리 잡아 영어권에서는 dewy skin, glass skin으로 옮겨진다.", "definition_i18n": {"de": "Haut mit feuchtem, durchfeuchtetem Glanz — oder das Make-up, das ihn erzeugt. Entscheidend ist, dass der Schimmer wie von innen aufsteigende Feuchtigkeit wirkt, nicht wie aufgelegter Glitzer, weshalb er zugleich mit dem Hautzustand angibt. Er wurde zum Markenzeichen der K-Beauty und reist als Dewy Skin oder Glass Skin.", "en": "Skin that shines with a wet, hydrated finish — or the makeup that produces it. The point is that the glow should read as moisture rising from inside, not glitter sitting on top, so it doubles as a brag about skin condition. It became the signature K-beauty finish and travels abroad as dewy skin or glass skin.", "es": "Piel que brilla con acabado húmedo e hidratado, o el maquillaje que lo consigue. La clave es que el brillo parezca humedad que sube desde dentro, no purpurina encima, así que también presume del estado de la piel. Se ha vuelto el acabado insignia del K-beauty y viaja como dewy skin o glass skin.", "ja": "水分を含んだようにしっとり輝く肌、またはそう見せるメイク。ラメの輝きではなく「内側から水分が満ちて透ける光」に見えることが肝で、塗って作ると同時に肌状態の自慢でもある。K-ビューティーを代表する肌表現として定着し、英語圏では dewy skin、glass skin と訳される。", "vi": "Làn da bóng ẩm căng mọng, hoặc lớp trang điểm tạo ra hiệu ứng đó. Điểm mấu chốt là ánh bóng phải trông như độ ẩm dâng từ bên trong chứ không phải nhũ đắp lên trên, nên nó cũng là cách khoe da đẹp. Đây đã thành kiểu da đặc trưng của K-beauty, ra nước ngoài gọi là dewy skin hay glass skin."}}]'::jsonb, '''물''과 ''광(光)''을 붙인 조어. 2000년대 뷰티 업계와 잡지가 ''물광 메이크업'', ''물광 주사''를 밀면서 일반어가 됐고, 2008년 신문 기사에도 이미 설명 없이 등장한다. 어느 브랜드나 기사가 처음 퍼뜨렸는지는 출처마다 설명이 달라 확정하지 않는다.', '{"de": "Zusammensetzung aus 물 (Wasser) und 광 (光, Glanz). In den 2000ern wurde es allgemein, als die Beauty-Presse 물광 메이크업 und 물광 주사 (eine Glow-Spritze) bewarb; in einem Zeitungsartikel von 2008 steht es bereits unerklärt. Die Quellen sind uneins, welche Marke oder welcher Artikel es zuerst verbreitete — daher keine Nennung.", "en": "A compound of 물 (water) and 광 (光, shine). It went general in the 2000s as the beauty press pushed 물광 메이크업 and 물광 주사 (a glow-boosting injection), and by a 2008 newspaper article it already appears unglossed. Sources disagree on which brand or article spread it first, so none is named.", "es": "Compuesto de 물 (agua) y 광 (光, brillo). Se generalizó en los 2000 cuando la prensa de belleza impulsó el 물광 메이크업 y la 물광 주사 (inyección para dar luminosidad), y en un artículo de prensa de 2008 ya aparece sin glosar. Las fuentes no coinciden sobre qué marca o artículo lo difundió primero, así que no se nombra.", "ja": "「물(水)」と「광(光)」を合わせた造語。2000年代に美容業界と雑誌が「水光メイク」「水光注射」を押し出して一般化し、2008年の新聞記事にはすでに説明なしで登場する。どのブランドや記事が最初に広めたかは出典によって異なり確定しない。", "vi": "Ghép 물 (nước) và 광 (光, ánh sáng). Nó thành từ phổ thông vào thập niên 2000 khi báo làm đẹp đẩy mạnh 물광 메이크업 và 물광 주사 (mũi tiêm làm sáng da), và trên một bài báo năm 2008 nó đã xuất hiện không cần chú thích. Các nguồn không thống nhất thương hiệu hay bài báo nào lan truyền đầu tiên nên không nêu tên."}'::jsonb, '''물광 나다 / 물광 내다 / 물광 피부''처럼 쓴다. 같은 계열로 꿀광(더 노랗고 진한 광), 윤광(은은한 광)이 있고, 반대는 광 없이 보송하게 마무리하는 ''매트''다. 칭찬으로 쓰이는 말이라 부담 없이 쓸 수 있다.', '{"de": "Verwendet als 물광 나다 (glänzen), 물광 내다 (Glanz erzeugen), 물광 피부 (Glow-Haut). Verwandt sind 꿀광 (wärmerer, honigfarbener Glanz) und 윤광 (sanfter Schimmer); das Gegenteil ist 매트, ein glanzfreies mattes Finish. Es ist ein Kompliment und lässt sich unbesorgt verwenden.", "en": "Used as 물광 나다 (to have a glow), 물광 내다 (to create one), 물광 피부 (glowy skin). Neighbors in the same family are 꿀광 (a warmer, honeyed glow) and 윤광 (a soft sheen); the opposite is 매트, a shine-free matte finish. It is a compliment, so it is safe to use freely.", "es": "Se usa como 물광 나다 (tener brillo), 물광 내다 (crearlo), 물광 피부 (piel luminosa). En la misma familia están 꿀광 (un brillo más dorado) y 윤광 (un lustre suave); lo contrario es 매트, el acabado sin brillo. Es un halago, así que se puede usar sin reparos.", "ja": "「물광 나다(つやが出る)」「물광 내다(つやを出す)」「물광 피부(水光肌)」のように使う。同系統に꿀광(より黄みの強いつや)、윤광(ほのかなつや)があり、反対はつやを抑えた「매트(マット)」。褒め言葉なので気兼ねなく使える。", "vi": "Dùng kiểu 물광 나다 (lên bóng), 물광 내다 (tạo độ bóng), 물광 피부 (da bóng khoẻ). Cùng họ có 꿀광 (bóng ngả vàng đậm hơn) và 윤광 (bóng nhẹ dịu); ngược lại là 매트, lớp nền lì không bóng. Đây là lời khen nên dùng thoải mái."}'::jsonb, array['파데', '꾸안꾸']::text[], null, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Dewy glow / glass skin"}, {"lang": "🇯🇵 JA", "text": "水光肌・ツヤ肌"}, {"lang": "🇨🇳 ZH", "text": "水光肌"}, {"lang": "🇻🇳 VI", "text": "Da bóng căng mọng"}, {"lang": "🇪🇸 ES", "text": "Piel glow / efecto húmedo"}, {"lang": "🇩🇪 DE", "text": "Dewy Glow / Glass Skin"}]'::jsonb),
('516', '쌩얼', 'Ssaeng-Eol', 'beauty', null, '화장 하나도 안 한 맨얼굴', '{"de": "Ein völlig ungeschminktes Gesicht", "en": "A completely bare, no-makeup face", "es": "La cara totalmente lavada, sin nada de maquillaje", "ja": "化粧を一切していない素顔", "vi": "Mặt mộc hoàn toàn, không trang điểm"}'::jsonb, '[쌩얼]', '[{"type": "명사", "examples": [{"de": "Ich bleibe heute eh daheim, also bin ich ungeschminkt raus.", "es": "Hoy me quedo en casa, así que salí con la cara lavada.", "ja": "今日は家にいるだけだからすっぴんで出てきた。", "vi": "Hôm nay mình chỉ ở nhà nên để mặt mộc ra luôn.", "eng": "I''m staying in all day, so I came out bare-faced.", "kor": "오늘 집에만 있을 거라 그냥 쌩얼로 나왔어."}, {"de": "Ein ungeschminktes Foto zu posten braucht echt Mut.", "es": "Subir una foto sin maquillaje requiere valor de verdad.", "ja": "すっぴん写真上げるの、本当に勇気いるわ。", "vi": "Đăng ảnh mặt mộc hoá ra cần dũng khí thật sự.", "eng": "Posting a bare-faced photo takes actual courage, it turns out.", "kor": "쌩얼 사진 올리는 거 진짜 용기 필요하더라."}], "definition": "화장을 전혀 하지 않은 맨얼굴. 표준어 ''민낯''과 가리키는 대상은 같지만, 쌩얼에는 ''화장한 모습과 비교해서 보는 얼굴''이라는 구경거리 뉘앙스가 붙어 있어 연예 기사와 SNS에서 훨씬 자주 쓰인다. 그래서 ''쌩얼 공개'', ''쌩얼이 더 예쁘다'' 같은 평가하는 문장에 잘 붙는다.", "definition_i18n": {"de": "Ein Gesicht ganz ohne Make-up. Es meint dasselbe wie das Standardwort 민낯, doch 쌩얼 hat einen Schaustück-Beiklang — das Gesicht gemessen an der geschminkten Version — weshalb Klatschpresse und Social Media dazu greifen. Es hängt sich leicht an wertende Wendungen wie 쌩얼 공개 (zeigt ihr ungeschminktes Gesicht) oder 쌩얼이 더 예쁘다 (ohne Make-up hübscher).", "en": "A face with no makeup at all. It points at the same thing as the standard word 민낯, but 쌩얼 carries a spectacle edge — the face as measured against the made-up version — which is why entertainment news and social media reach for it. It attaches easily to judging phrases like 쌩얼 공개 (revealing her bare face) or 쌩얼이 더 예쁘다 (she is prettier without makeup).", "es": "Una cara sin nada de maquillaje. Señala lo mismo que la palabra estándar 민낯, pero 쌩얼 lleva un aire de espectáculo —la cara medida contra su versión maquillada—, por eso la prensa del corazón y las redes la prefieren. Encaja fácil en frases valorativas como 쌩얼 공개 (enseña su cara lavada) o 쌩얼이 더 예쁘다 (está más guapa sin maquillaje).", "ja": "化粧を一切していない素顔。標準語「민낯」と指すものは同じだが、「쌩얼」には化粧した姿と比べて見るという見世物的なニュアンスがあり、芸能記事やSNSではこちらがはるかに多い。「쌩얼 공개(素顔公開)」「쌩얼이 더 예쁘다(すっぴんのほうがきれい)」のような評価文に付きやすい。", "vi": "Khuôn mặt không trang điểm chút nào. Nó chỉ cùng một thứ với từ chuẩn 민낯, nhưng 쌩얼 mang sắc thái trưng ra — khuôn mặt được đem so với bản đã trang điểm — nên báo giải trí và mạng xã hội chuộng dùng. Nó dễ đi kèm câu đánh giá như 쌩얼 공개 (lộ mặt mộc) hay 쌩얼이 더 예쁘다 (để mặt mộc còn xinh hơn)."}}]'::jsonb, '날것 그대로를 뜻하는 접두사 ''생-(生)''에 ''얼굴''을 붙인 ''생얼''을, 더 센 느낌을 주려고 된소리 ''쌩''으로 발음·표기하면서 굳었다. 2000년대 연예 기사에서 ''쌩얼 공개''류 표현이 퍼지며 일반어가 됐다는 서술이 있으나 정확한 시점과 최초 사용자는 출처마다 다르거나 아예 없어 특정하지 않는다.', '{"de": "Von 생얼 — Präfix 생- (roh, wie es ist) plus 얼굴 (Gesicht) — wobei 생 als gespanntes 쌩 gesprochen und geschrieben wird, für mehr Nachdruck. Eine Darstellung führt die Verbreitung auf Promi-Schlagzeilen der 2000er über ungeschminkte Auftritte zurück, doch die Quellen widersprechen sich oder schweigen zu Datum und Erstverwendung, daher keine Festlegung.", "en": "From 생얼 — the prefix 생- (raw, as-is) plus 얼굴 (face) — with 생 pronounced and written as the tense 쌩 for extra force. One account says it went mainstream through 2000s entertainment headlines about stars revealing their bare faces, but sources disagree or stay silent on the exact date and first user, so none is claimed.", "es": "De 생얼 —el prefijo 생- (crudo, tal cual) más 얼굴 (cara)— con 생 pronunciado y escrito como el tenso 쌩 para dar más fuerza. Se dice que se popularizó con los titulares de prensa rosa de los 2000 sobre famosas enseñando la cara lavada, pero las fuentes discrepan o callan sobre la fecha exacta y el primer uso, así que no se afirma ninguna.", "ja": "生のままを意味する接頭辞「생-(生)」に「얼굴(顔)」を付けた「생얼」を、より強い響きにするため濃音「쌩」で発音・表記して定着した。2000年代の芸能記事の「素顔公開」系表現で一般化したという説明もあるが、正確な時期と初出は出典によって異なるか記載がなく特定しない。", "vi": "Từ 생얼 — tiền tố 생- (sống, để nguyên) ghép với 얼굴 (mặt) — rồi 생 được phát âm và viết thành âm căng 쌩 cho mạnh hơn. Có ý kiến cho rằng nó phổ biến nhờ tin giải trí thập niên 2000 về sao lộ mặt mộc, nhưng các nguồn không thống nhất hoặc không nói về mốc chính xác và người dùng đầu tiên, nên không khẳng định."}'::jsonb, '어느 쪽으로 검색해도 항목 하나 — ''생얼''로도 쓴다. 자기 얼굴을 두고 쓰면 편한 말이지만, 남의 쌩얼을 두고 예쁘다·못났다 평하는 순간 그 자체가 외모 평가가 되니 조심해야 한다.', '{"de": "Egal wie man sucht, es gibt nur diesen Eintrag — 생얼 ist dasselbe Wort. Übers eigene Gesicht ist es harmlos, doch sobald man das ungeschminkte Gesicht anderer als hübsch oder nicht bewertet, ist das ein Aussehensurteil — also Vorsicht.", "en": "Searching either form lands on this one entry — 생얼 is the same word. About your own face it is casual and harmless, but the moment you rate someone else''s bare face as pretty or not, that is appearance-judging, so tread carefully.", "es": "Busques como busques es una sola entrada: 생얼 es la misma palabra. Sobre tu propia cara es una palabra inocua, pero en cuanto valoras la cara lavada de otra persona como guapa o no, eso ya es juzgar el aspecto; cuidado.", "ja": "どちらで検索しても項目は一つ——「생얼」も同じ語。自分の顔について言う分には気楽な語だが、他人のすっぴんを美醜で評した瞬間それ自体が外見評価になるので注意。", "vi": "Tìm kiểu nào cũng ra một mục — 생얼 là cùng một từ. Nói về mặt mình thì thoải mái, nhưng hễ bạn khen chê mặt mộc của người khác đẹp hay xấu thì đó đã là phán xét ngoại hình rồi, nên cẩn thận."}'::jsonb, array['꾸안꾸', '마기꾼', '화떡']::text[], array['생얼']::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Bare face / no-makeup face"}, {"lang": "🇯🇵 JA", "text": "すっぴん・素顔"}, {"lang": "🇨🇳 ZH", "text": "素颜"}, {"lang": "🇻🇳 VI", "text": "Mặt mộc"}, {"lang": "🇪🇸 ES", "text": "Cara lavada / sin maquillaje"}, {"lang": "🇩🇪 DE", "text": "Ungeschminktes Gesicht"}]'::jsonb),
('517', '다크닝', 'Da-Keu-Ning', 'beauty', null, '시간이 지나면서 화장이 어두워지고 얼굴이 칙칙해지는 현상', '{"de": "Foundation, die im Lauf des Tages nachdunkelt", "en": "Base makeup oxidizing darker over the day", "es": "La base que se oxida y oscurece con las horas", "ja": "時間とともにベースメイクが暗くくすむ現象", "vi": "Lớp nền bị oxy hoá, tối màu dần theo thời gian"}'::jsonb, '[다크닝]', '[{"type": "명사", "examples": [{"de": "Oxidiert diese Foundation stark? Nachmittags wird mein Gesicht immer fahl.", "es": "¿Esta base se oxida mucho? Por la tarde la cara se me apaga.", "ja": "このファンデ、暗くなるのひどい?午後になると顔がくすむんだよね。", "vi": "Kem nền này có xuống tông nhiều không? Cứ chiều là mặt mình xỉn.", "eng": "Does this foundation oxidize badly? My face goes dull every afternoon.", "kor": "이 파데 다크닝 심해? 오후만 되면 얼굴 칙칙해져서."}, {"de": "Mit Puder den Glanz abzufangen mindert das Nachdunkeln etwas.", "es": "Si lo sellas con polvos para controlar el aceite, se oxida menos.", "ja": "パウダーで皮脂を抑えると暗くなるのが少しマシになる。", "vi": "Dặm phấn phủ kiềm dầu thì đỡ bị xuống tông hơn.", "eng": "Setting it with powder to control oil cuts down the oxidizing a bit.", "kor": "파우더로 유분 잡아 주면 다크닝 좀 덜해."}], "definition": "아침에 바를 땐 잘 맞던 베이스 화장품 색이 시간이 지나면서 어두워져 얼굴이 칙칙하고 얼룩덜룩해 보이는 현상. 피부에서 나온 피지·땀이 색소와 섞이고 공기와 만나 산화하면서 생긴다. 립 제품이 입술에 색소 침착을 남기는 것도 다크닝이라 부른다. 파운데이션·쿠션 후기에서 밀착력과 함께 거의 항상 따지는 항목이다.", "definition_i18n": {"de": "Wenn Foundation, die morgens noch passte, im Lauf der Stunden nachdunkelt und das Gesicht fahl und fleckig wirken lässt. Talg und Schweiß vermischen sich mit dem Pigment und oxidieren an der Luft. Auch Lippenprodukte, die Verfärbungen hinterlassen, heißen 다크닝. Neben der Haltbarkeit ist es der Punkt, den jedes Foundation- und Cushion-Review prüft.", "en": "When base makeup that matched your skin in the morning darkens over the hours, leaving the face dull and patchy. Sebum and sweat mix with the pigment and oxidize on contact with air. Lip products leaving a stain on the lips get called 다크닝 too. Alongside staying power, it is the thing every foundation and cushion review checks.", "es": "Cuando la base que por la mañana encajaba con tu piel se oscurece con las horas y deja la cara apagada y desigual. El sebo y el sudor se mezclan con el pigmento y se oxidan al contacto con el aire. También se llama 다크닝 a la mancha que dejan algunos labiales. Junto con la duración, es lo que revisa toda reseña de base o cushion.", "ja": "朝塗ったときはぴったりだったベースメイクの色が時間とともに暗くなり、顔がくすんでムラに見える現象。皮脂や汗が色素と混ざり、空気に触れて酸化することで起きる。リップ製品が唇に色素沈着を残すことも다크닝と呼ぶ。ファンデ・クッションのレビューでは密着力と並んでほぼ必ず問われる項目。", "vi": "Khi lớp nền buổi sáng còn hợp da lại tối dần theo giờ, khiến mặt xỉn và loang lổ. Dầu thừa và mồ hôi trộn với sắc tố rồi oxy hoá khi gặp không khí. Việc son để lại vết thâm trên môi cũng được gọi là 다크닝. Cùng với độ bám, đây là mục mà mọi bài đánh giá kem nền hay cushion đều soi."}}]'::jsonb, '영어 darkening을 그대로 들여온 말. 화장품 업계의 기술 용어로 쓰이다가 소비자 후기 문화가 자리 잡으면서 일반 사용자들도 쓰는 말이 됐다. 2010년 신문 기사에 이미 ''다크닝''이 설명과 함께 등장하고, 2025년 기사에서는 설명 없이 쓰인다.', '{"de": "Eine direkte Entlehnung des englischen ''darkening''. Erst Fachjargon der Kosmetikbranche, wurde es mit der Review-Kultur alltäglich. Ein Zeitungsartikel von 2010 führt es noch mit Erklärung ein; 2025 steht es unerklärt in der Presse.", "en": "A straight borrowing of English ''darkening''. It started as cosmetics-industry jargon and passed into ordinary use as consumer review culture took hold. A 2010 newspaper article already introduces 다크닝 with a gloss; by 2025 the press uses it unexplained.", "es": "Préstamo directo del inglés ''darkening''. Empezó como jerga de la industria cosmética y pasó al uso común al asentarse la cultura de las reseñas. Un artículo de 2010 ya lo presenta con explicación; en 2025 la prensa lo usa sin glosar.", "ja": "英語 darkening をそのまま取り入れた語。化粧品業界の技術用語だったものが、消費者レビュー文化の定着とともに一般ユーザーの語になった。2010年の新聞記事にはすでに説明付きで登場し、2025年の記事では説明なしで使われている。", "vi": "Mượn thẳng từ tiếng Anh ''darkening''. Ban đầu là thuật ngữ ngành mỹ phẩm, rồi thành từ thông dụng khi văn hoá đánh giá sản phẩm lên ngôi. Một bài báo năm 2010 đã giới thiệu kèm giải thích; đến 2025 báo chí dùng thẳng không chú."}'::jsonb, '결과를 가리키는 명사라 ''다크닝 나다 / 다크닝 생기다 / 다크닝 심하다''로 쓴다. 제품 탓을 할 때 쓰는 말이라 사람에게 쓰지 않는다. 피지가 많은 피부일수록 잘 생겨서 ''수부지''나 지성 피부 후기에 특히 자주 나온다.', '{"de": "Es benennt ein Ergebnis und steht mit 다크닝 나다 / 생기다 / 심하다 (auftreten, entstehen, stark sein). Es macht das Produkt verantwortlich, nie eine Person. Fettigere Haut trifft es häufiger, daher taucht es ständig in Reviews von 수부지- und Mischhaut-Nutzern auf.", "en": "It names a result, so it takes 다크닝 나다 / 생기다 / 심하다 (to show up, to occur, to be bad). It blames the product, never a person. Oilier skin sees it more, so it comes up constantly in reviews from 수부지 and oily-skin users.", "es": "Nombra un resultado, así que va con 다크닝 나다 / 생기다 / 심하다 (aparecer, producirse, ser grave). Culpa al producto, nunca a una persona. Las pieles más grasas lo sufren más, por eso sale sin parar en reseñas de 수부지 y piel grasa.", "ja": "結果を指す名詞なので「다크닝 나다/생기다/심하다(出る・起きる・ひどい)」の形で使う。製品を責める語で、人には使わない。皮脂が多い肌ほど起きやすく、「수부지」や脂性肌のレビューに特に頻出する。", "vi": "Nó gọi tên một kết quả nên đi với 다크닝 나다 / 생기다 / 심하다 (bị, xảy ra, nặng). Từ này đổ lỗi cho sản phẩm, không bao giờ cho người. Da càng dầu càng hay gặp, nên xuất hiện liên tục trong đánh giá của người da 수부지 và da dầu."}'::jsonb, array['파데', '수부지', '물광']::text[], null, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Oxidation / makeup darkening"}, {"lang": "🇯🇵 JA", "text": "ファンデの酸化(色が暗くなる)"}, {"lang": "🇨🇳 ZH", "text": "底妆氧化变暗"}, {"lang": "🇻🇳 VI", "text": "Kem nền xuống tông (oxy hoá)"}, {"lang": "🇪🇸 ES", "text": "Oxidación de la base"}, {"lang": "🇩🇪 DE", "text": "Nachdunkeln der Foundation"}]'::jsonb),
('518', '무쌍', 'Mu-Ssang', 'beauty', null, '쌍꺼풀이 없는 눈', '{"de": "Monolid — ein Auge ohne Lidfalte", "en": "A monolid — an eye with no crease", "es": "Ojo sin pliegue (monopárpado)", "ja": "二重のない目(一重)", "vi": "Mắt một mí, không có nếp mí"}'::jsonb, '[무쌍]', '[{"type": "명사", "examples": [{"de": "Ich habe Monolids, bei dieser Art Lidschatten schmiert alles ab.", "es": "Tengo monopárpado, así que esta sombra se me transfiere entera.", "ja": "私一重だから、こういうアイシャドウ塗ると全部こすれちゃう。", "vi": "Mình mắt một mí nên đánh loại phấn mắt này là bị lem hết.", "eng": "I have monolids, so this kind of eyeshadow just transfers onto the lid.", "kor": "나 무쌍이라 이런 아이섀도 바르면 다 묻어나."}, {"de": "Kannst du Make-up-Tutorials für Monolids empfehlen?", "es": "¿Me recomiendas tutoriales de maquillaje para monopárpado?", "ja": "一重メイクの動画おすすめ教えて。", "vi": "Gợi ý mình mấy video trang điểm cho mắt một mí với.", "eng": "Can you recommend some monolid makeup tutorials?", "kor": "무쌍 메이크업 영상 좀 추천해 줘."}], "definition": "쌍꺼풀이 없는 눈. ''무(無)쌍꺼풀''을 줄인 말이다. 겉에서는 선이 안 보여도 속으로 접히면 속쌍, 선이 뚜렷하게 드러나면 유쌍 또는 겉쌍이라고 해서 눈 형태를 셋으로 나눈다. 아이 메이크업 방법이 형태마다 완전히 달라서, 한국 뷰티 콘텐츠는 거의 항상 ''무쌍용 / 속쌍용''으로 나눠 설명한다.", "definition_i18n": {"de": "Ein Auge ohne Lidfalte, gekürzt aus 무쌍꺼풀. Das Koreanische unterscheidet drei Lidformen: 무쌍 (keine Falte), 속쌍 (eine innen verborgene Falte) und 유쌍 bzw. 겉쌍 (eine deutlich sichtbare Falte). Da die Make-up-Technik je nach Form völlig anders ist, trennt koreanischer Beauty-Content seine Tipps fast immer in 무쌍용 und 속쌍용.", "en": "An eye with no double eyelid — clipped from 무쌍꺼풀. Korean splits eye shapes into three: 무쌍 (no crease), 속쌍 (a crease hidden inside, invisible from outside) and 유쌍 or 겉쌍 (a clearly visible crease). Because eye makeup technique changes completely with the shape, Korean beauty content almost always splits its advice into 무쌍용 and 속쌍용 versions.", "es": "Un ojo sin pliegue palpebral, recorte de 무쌍꺼풀. El coreano divide las formas de ojo en tres: 무쌍 (sin pliegue), 속쌍 (pliegue oculto, no visible desde fuera) y 유쌍 o 겉쌍 (pliegue bien marcado). Como la técnica de maquillaje cambia por completo según la forma, el contenido de belleza coreano casi siempre separa sus consejos en versión 무쌍용 y 속쌍용.", "ja": "二重のない目。「무쌍꺼풀(無二重まぶた)」の略。外からは見えなくても内側で折れていれば속쌍(奥二重)、線がはっきり出ていれば유쌍/겉쌍(二重)と、目の形を三つに分ける。アイメイクの方法が形ごとに全く違うため、韓国のビューティーコンテンツはほぼ必ず「무쌍용/속쌍용」と分けて説明する。", "vi": "Mắt không có nếp mí đôi, rút gọn từ 무쌍꺼풀. Tiếng Hàn chia dáng mắt làm ba: 무쌍 (không nếp), 속쌍 (nếp giấu bên trong, ngoài không thấy) và 유쌍 hay 겉쌍 (nếp hiện rõ). Vì cách đánh mắt khác hẳn nhau theo từng dáng, nội dung làm đẹp Hàn gần như luôn tách hướng dẫn thành bản 무쌍용 và 속쌍용."}}]'::jsonb, '''무(無)''에 ''쌍꺼풀''을 붙인 ''무쌍꺼풀''을 두 음절로 줄인 말. 성형외과와 뷰티 커뮤니티에서 눈 형태를 무쌍·속쌍·유쌍 셋으로 나눠 부르면서 굳었다. 이 뜻으로 언제부터 쓰였는지 밝힌 출처가 없어 시기는 특정하지 않는다. 표준국어대사전의 ''무쌍(無雙)''은 ''견줄 만한 것이 없음''이라는 전혀 다른 말이다.', '{"de": "무쌍꺼풀 (無 ''ohne'' + 쌍꺼풀 ''Doppellid'') auf zwei Silben gekürzt. Es verfestigte sich, als Kliniken und Beauty-Communities die Dreiteilung 무쌍 / 속쌍 / 유쌍 etablierten. Keine Quelle datiert diese Bedeutung, daher keine Festlegung. Das 무쌍 (無雙) im Standardwörterbuch ist ein anderes Wort und heißt ''unvergleichlich''.", "en": "무쌍꺼풀 (無 ''none'' + 쌍꺼풀 ''double eyelid'') clipped to two syllables. It hardened as clinics and beauty communities settled on the three-way split 무쌍 / 속쌍 / 유쌍. No source dates this sense, so none is claimed. The Standard Korean Dictionary''s 무쌍 (無雙) is an unrelated word meaning ''without equal''.", "es": "무쌍꺼풀 (無 ''sin'' + 쌍꺼풀 ''párpado doble'') recortado a dos sílabas. Cuajó cuando clínicas y comunidades de belleza fijaron la división en 무쌍 / 속쌍 / 유쌍. Ninguna fuente data esta acepción, así que no se afirma fecha. El 무쌍 (無雙) del Diccionario Estándar es otra palabra, ''sin igual''.", "ja": "「무(無)」に「쌍꺼풀(二重まぶた)」を付けた「무쌍꺼풀」を二音節に縮めた語。美容外科とビューティーコミュニティが무쌍/속쌍/유쌍の三分類を定着させる中で固まった。この意味での初出時期を示す出典はなく特定しない。標準国語大辞典の「무쌍(無雙)」は「並ぶものがない」という全く別の語。", "vi": "무쌍꺼풀 (無 ''không'' + 쌍꺼풀 ''mí đôi'') rút còn hai âm tiết. Nó đọng lại khi các phòng khám và cộng đồng làm đẹp chốt cách chia ba 무쌍 / 속쌍 / 유쌍. Không nguồn nào ghi mốc thời gian của nghĩa này nên không nêu. Từ 무쌍 (無雙) trong Từ điển Chuẩn là từ khác hẳn, nghĩa là ''không ai sánh bằng''."}'::jsonb, '눈 형태를 가리키는 중립적인 분류어라 자기 눈을 설명할 때 그냥 쓰면 된다. 다만 ''무쌍이라 답답해 보인다''처럼 평가와 붙여 쓰면 외모 비하가 되니 주의. 검색할 땐 ''무쌍 메이크업'', ''무쌍 아이라인''처럼 붙여 쓰면 관련 콘텐츠가 바로 나온다.', '{"de": "Es ist eine neutrale Formbezeichnung, das eigene Auge damit zu beschreiben ist völlig normal. An ein Urteil gekoppelt — 무쌍이라 답답해 보인다 (mit Monolid wirkt der Blick zu) — wird es zur Abwertung des Aussehens, also Vorsicht. Zum Suchen kombinieren: 무쌍 메이크업, 무쌍 아이라인.", "en": "It is a neutral shape label, so describing your own eyes with it is perfectly ordinary. Bolted onto a judgment — 무쌍이라 답답해 보인다 (monolids make you look closed-off) — it turns into an appearance put-down, so watch that. As a search term, pair it up: 무쌍 메이크업, 무쌍 아이라인.", "es": "Es una etiqueta neutra de forma, así que describir tus propios ojos con ella es de lo más normal. Pegada a un juicio —무쌍이라 답답해 보인다 (con monopárpado se te ve la mirada cerrada)— se convierte en un desprecio estético, ojo con eso. Para buscar, combínala: 무쌍 메이크업, 무쌍 아이라인.", "ja": "目の形を指す中立的な分類語なので、自分の目を説明するのに普通に使える。ただし「무쌍이라 답답해 보인다(一重だから重く見える)」のように評価と結びつけると容姿の貶しになるので注意。検索では「무쌍 메이크업」「무쌍 아이라인」のように組み合わせるとすぐ出る。", "vi": "Đây là nhãn dáng mắt trung tính, nên dùng để tả mắt mình là hoàn toàn bình thường. Nhưng gắn kèm lời phán xét — 무쌍이라 답답해 보인다 (mắt một mí trông bí bí) — thì thành chê ngoại hình, cần lưu ý. Khi tìm kiếm hãy ghép cụm: 무쌍 메이크업, 무쌍 아이라인."}'::jsonb, array['쌩얼', '화떡', '마기꾼']::text[], array['무쌍꺼풀']::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Monolid (no double eyelid)"}, {"lang": "🇯🇵 JA", "text": "一重まぶた"}, {"lang": "🇨🇳 ZH", "text": "单眼皮"}, {"lang": "🇻🇳 VI", "text": "Mắt một mí"}, {"lang": "🇪🇸 ES", "text": "Monopárpado"}, {"lang": "🇩🇪 DE", "text": "Monolid / einfaches Lid"}]'::jsonb),
('519', 'MLBB', 'Em-El-Bi-Bi', 'beauty', null, '내 입술색인데 조금 더 예쁜, 화장한 티 안 나는 립 색', '{"de": "Ein Lippenton, der aussieht wie die eigenen Lippen, nur besser", "en": "A lip shade that looks like your own lips, only better", "es": "Un tono de labios que parece el tuyo, pero mejor", "ja": "自分の唇の色そのままで少しだけきれいなリップ色", "vi": "Tông son trông y như màu môi thật, chỉ đẹp hơn chút"}'::jsonb, '[엠엘비비]', '[{"type": "명사", "examples": [{"de": "Dieser Tint ist voll MLBB — man sieht gar nicht, dass ich was trage.", "es": "Este tinte es MLBB total: ni se nota que llevo algo.", "ja": "このティント完全にMLBB。塗っても化粧した感じが全然しない。", "vi": "Cây tint này đúng chuẩn MLBB, tô lên chẳng ai nhận ra mình có đánh son.", "eng": "This tint is total MLBB — you can''t even tell I''m wearing anything.", "kor": "이 틴트 완전 MLBB야. 발라도 화장한 티 하나도 안 나."}, {"de": "Fürs Vorstellungsgespräch lass die knalligen Töne und nimm einen MLBB mit.", "es": "Para una entrevista deja los tonos llamativos y llévate un MLBB.", "ja": "面接のときは派手な色じゃなくてMLBBを一本持っていきな。", "vi": "Đi phỏng vấn thì bỏ mấy màu nổi đi, mang theo một cây MLBB thôi.", "eng": "For an interview skip the bold shades and just bring an MLBB.", "kor": "면접 갈 땐 튀는 색 말고 MLBB 하나 챙겨 가."}], "definition": "My Lips But Better의 머리글자. 내 원래 입술색과 비슷하면서 살짝 더 화사하고 생기 있어 보이게 만드는 립 색을 가리킨다. 말린 장미색, 누드 베이지 계열이 대표적이고, 발라도 ''립 발랐네''가 아니라 ''오늘 안색 좋네'' 소리가 나오는 것이 성공 기준이다. 립 제품 후기와 쇼핑 검색에서 색 계열을 가리키는 사실상의 표준 태그로 쓰인다.", "definition_i18n": {"de": "Die Initialen von My Lips But Better: ein Lippenton nahe der natürlichen Lippenfarbe, nur eine Spur frischer und lebendiger. Klassiker sind Dried-Rose- und Nude-Beige-Familien, und als gelungen gilt es, wenn andere sagen, man sehe gut aus — nicht, dass man Lippenstift trage. In Reviews und Shop-Filtern dient es als De-facto-Tag für diese ganze Farbfamilie.", "en": "The initials of My Lips But Better: a lip shade close to your natural lip color but a touch brighter and livelier. Dried-rose and nude-beige families are the classics, and the test of success is that people say you look well rather than that they notice lipstick. In product reviews and shopping filters it works as the de facto tag for that whole color family.", "es": "Las iniciales de My Lips But Better: un tono de labios cercano al color natural pero un punto más luminoso y vivo. Los clásicos son la familia rosa seco y el nude beige, y la prueba del éxito es que te digan que tienes buena cara, no que llevas pintalabios. En reseñas y filtros de compra funciona como la etiqueta de facto de toda esa gama.", "ja": "My Lips But Better の頭文字。自分の唇の色に近いまま、少しだけ明るく血色よく見せるリップ色を指す。ドライローズやヌードベージュ系が代表で、「リップ塗ったね」ではなく「今日顔色いいね」と言われれば成功。リップのレビューや通販検索では、この色系統を指す事実上の標準タグとして使われる。", "vi": "Viết tắt của My Lips But Better: tông son gần với màu môi tự nhiên nhưng tươi và có sức sống hơn một chút. Kinh điển là nhóm hồng đất khô và be nude, và dấu hiệu thành công là người ta khen bạn trông tươi tắn chứ không nhận ra bạn đang tô son. Trong bài đánh giá và bộ lọc mua sắm, nó là thẻ mặc định cho cả nhóm màu này."}}]'::jsonb, '영어권 뷰티 유튜버·매거진이 쓰던 표현 My Lips But Better의 머리글자. 2010년대에 국내 뷰티 잡지와 브랜드 마케팅을 타고 들어와 번역 없이 알파벳 그대로 굳었다. 언제 어떤 경로로 처음 들어왔는지를 밝힌 출처는 없어 특정하지 않는다. 한글로는 ''엠엘비비''라고 적기도 하지만 실제 표기는 알파벳이 압도적이다.', '{"de": "Die Initialen von My Lips But Better, einem Ausdruck englischsprachiger Beauty-YouTuber und Magazine. Er kam in den 2010ern über Beauty-Presse und Markenmarketing nach Korea und blieb unübersetzt in lateinischen Buchstaben. Keine Quelle nennt Weg oder Jahr, daher keine Festlegung. Gelegentlich schreibt man 엠엘비비 in Hangul, doch die Alphabetschreibung überwiegt.", "en": "The initials of My Lips But Better, a phrase from English-language beauty YouTubers and magazines. It entered Korea through beauty press and brand marketing in the 2010s and stuck in Latin letters, untranslated. No source records the exact route or year, so none is claimed. It is occasionally written 엠엘비비 in Hangul, but the alphabet spelling dominates.", "es": "Las iniciales de My Lips But Better, expresión de youtubers y revistas de belleza anglosajonas. Entró en Corea a través de la prensa de belleza y el marketing de marcas en la década de 2010 y cuajó en alfabeto latino, sin traducir. Ninguna fuente registra la ruta ni el año exacto, así que no se afirma. A veces se escribe 엠엘비비 en hangul, pero la grafía en alfabeto domina.", "ja": "英語圏のビューティーYouTuberや雑誌が使っていた My Lips But Better の頭文字。2010年代に国内の美容誌とブランドのマーケティングを通じて入り、訳されずアルファベットのまま定着した。正確な流入時期や経路を示す出典はなく特定しない。ハングルで「엠엘비비」と書くこともあるが、実際の表記はアルファベットが圧倒的。", "vi": "Viết tắt của My Lips But Better, cụm từ của các YouTuber và tạp chí làm đẹp nói tiếng Anh. Nó vào Hàn qua báo làm đẹp và marketing thương hiệu trong thập niên 2010 rồi giữ nguyên chữ Latinh, không dịch. Không nguồn nào ghi lại đường đi hay năm chính xác nên không khẳng định. Đôi khi viết là 엠엘비비 bằng Hangul, nhưng cách viết chữ cái vẫn áp đảo."}'::jsonb, '''완전 MLBB다'', ''MLBB 립 추천''처럼 색을 칭찬하거나 찾을 때 쓴다. 읽을 때는 글자 그대로 ''엠엘비비''라고 읽는다. 어느 쪽으로 검색해도 항목 하나 — ''엠엘비비''도 같은 말이다.', '{"de": "Zum Loben oder Suchen eines Tons: 완전 MLBB다 (total MLBB), MLBB 립 추천 (empfiehl mir einen MLBB-Lippenstift). Gesprochen buchstabiert man es einfach: 엠엘비비. Egal wie man sucht, es gibt nur diesen Eintrag — 엠엘비비 ist dasselbe Wort.", "en": "Used to praise or hunt for a shade: 완전 MLBB다 (this is so MLBB), MLBB 립 추천 (recommend me an MLBB lip). Read aloud it is simply spelled out, 엠엘비비. Searching either form lands on this one entry — 엠엘비비 is the same word.", "es": "Se usa para alabar o buscar un tono: 완전 MLBB다 (es súper MLBB), MLBB 립 추천 (recomiéndame un labial MLBB). Se lee deletreado, 엠엘비비. Busques como busques es una sola entrada: 엠엘비비 es la misma palabra.", "ja": "「완전 MLBB다(完全にMLBB)」「MLBB 립 추천(MLBBリップおすすめ)」のように色を褒めたり探したりするときに使う。読むときは文字どおり「엠엘비비」。どちらで検索しても項目は一つ——「엠엘비비」も同じ語。", "vi": "Dùng để khen hoặc tìm màu son: 완전 MLBB다 (đúng chuẩn MLBB), MLBB 립 추천 (gợi ý son MLBB đi). Đọc lên thì đánh vần từng chữ, 엠엘비비. Tìm kiểu nào cũng ra một mục — 엠엘비비 là cùng một từ."}'::jsonb, array['꾸안꾸', '다크닝', '물광']::text[], array['엠엘비비']::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "MLBB (My Lips But Better)"}, {"lang": "🇯🇵 JA", "text": "MLBB(自然な血色リップ)"}, {"lang": "🇨🇳 ZH", "text": "MLBB(比原唇色更好看)"}, {"lang": "🇻🇳 VI", "text": "MLBB (son hợp màu môi thật)"}, {"lang": "🇪🇸 ES", "text": "MLBB (labios naturales mejorados)"}, {"lang": "🇩🇪 DE", "text": "MLBB (natürlicher Lippenton)"}]'::jsonb),
('520', '꿀피부', 'Kkul-Pi-Bu', 'beauty', null, '꿀을 바른 듯 매끈하고 윤기 나는 피부', '{"de": "Honighaut — makellos glatte, strahlende Haut", "en": "Honey skin — flawless, dewy, glowing skin", "es": "Piel de miel: lisa, luminosa y sin imperfecciones", "ja": "蜂蜜を塗ったようにつるつるで艶のある肌", "vi": "Da mật ong — mịn, căng bóng, không tì vết"}'::jsonb, '[꿀피부]', '[{"type": "명사", "examples": [{"de": "Deine Haut strahlt in letzter Zeit — was benutzt du?", "es": "Últimamente tienes una piel de miel, ¿qué usas?", "ja": "最近めっちゃ肌キレイじゃん、何使ってるの?", "vi": "Dạo này da bạn mịn bóng ghê, dùng gì vậy?", "eng": "Your skin is glowing lately — what are you using?", "kor": "너 요즘 꿀피부다? 뭐 써?"}, {"de": "Ich habe meine Feuchtigkeitscreme gewechselt, weil ich auch so eine Honighaut will.", "es": "Cambié de crema hidratante porque yo también quiero esa piel de miel.", "ja": "私もツヤ肌になりたくて保湿クリーム変えた。", "vi": "Mình đổi kem dưỡng ẩm vì cũng muốn có làn da mật ong.", "eng": "I switched moisturizers because I want that honey-skin glow too.", "kor": "나도 꿀피부 되고 싶어서 수분크림 바꿨어."}], "definition": "잡티 하나 없이 매끈하고, 꿀을 바른 것처럼 촉촉하게 윤이 나서 만져보고 싶어지는 피부. 화장으로 가린 것이 아니라 맨 피부 자체가 좋다는 뜻으로 쓰는 최고 수준의 칭찬이다. K뷰티가 지향하는 피부 상태를 한 단어로 요약할 때 쓴다.", "definition_i18n": {"de": "Haut, die so glatt und makellos ist und so feucht wie mit Honig bestrichen glänzt, dass man sie anfassen möchte. Es ist das größte Kompliment für Haut und meint ausdrücklich, dass die nackte Haut selbst gut ist — nicht dass das Make-up die Arbeit macht. Es fasst in einem Wort den Hautzustand zusammen, den K-Beauty anstrebt.", "en": "Skin so smooth and blemish-free, with a moist honey-like sheen, that you want to touch it. It is the highest compliment for skin, and it specifically means the bare skin itself is good — not that the makeup is doing the work. It is the one-word summary of the skin condition K-beauty aims for.", "es": "Piel tan lisa y sin imperfecciones, con un brillo húmedo como de miel, que dan ganas de tocarla. Es el mayor cumplido posible para la piel y significa concretamente que la piel desnuda es buena, no que el maquillaje lo esté disimulando. Resume en una palabra el estado de piel al que aspira el K-beauty.", "ja": "シミひとつなくつるつるで、蜂蜜を塗ったようにしっとり艶めいて、思わず触りたくなる肌。メイクで隠しているのではなく素肌そのものが良いという意味で使う最上級の褒め言葉。Kビューティーが目指す肌状態を一言で表す語。", "vi": "Làn da mịn màng không một khuyết điểm, căng bóng ẩm mượt như thoa mật ong, khiến người ta muốn chạm vào. Đây là lời khen cao nhất dành cho da, và nó hàm ý rõ ràng rằng chính làn da mộc đẹp chứ không phải nhờ lớp trang điểm che đi. Là cách tóm gọn trong một từ tình trạng da mà K-beauty hướng tới."}}]'::jsonb, '꿀 + 피부. 2009년 화장품 업계의 그해 신조어로 꼽힐 만큼 퍼진 말이고, 당시 이민정·고현정·송혜교 등 배우들의 맑고 촉촉한 피부를 가리키며 쓰였다. 좋은 것 앞에 ''꿀''을 붙이는 용법(꿀잼·꿀팁)과 같은 계열이다. 누가 처음 만들었는지는 출처에 나오지 않아 특정하지 않는다.', '{"de": "꿀 (Honig) + 피부 (Haut). Es verbreitete sich so stark, dass es 2009 zu den Neuwörtern der Kosmetikbranche gezählt wurde, damals für die klare, taufrische Haut von Schauspielerinnen wie Lee Min-jung, Go Hyun-jung und Song Hye-kyo. Es gehört zur selben Familie wie andere 꿀-Komposita für gute Dinge (꿀잼, 꿀팁). Keine Quelle nennt den Urheber.", "en": "꿀 (honey) + 피부 (skin). It spread far enough to be named one of the cosmetics industry''s neologisms of 2009, used then for the clear, dewy skin of actresses like Lee Min-jung, Go Hyun-jung and Song Hye-kyo. It belongs to the same family as other 꿀- compounds for good things (꿀잼, 꿀팁). No source names who coined it.", "es": "꿀 (miel) + 피부 (piel). Se extendió lo suficiente como para figurar entre los neologismos del sector cosmético de 2009, usado entonces para la piel limpia y jugosa de actrices como Lee Min-jung, Go Hyun-jung y Song Hye-kyo. Pertenece a la misma familia que otros compuestos con 꿀 para cosas buenas (꿀잼, 꿀팁). Ninguna fuente dice quién lo acuñó.", "ja": "꿀(蜂蜜)+피부(肌)。2009年の化粧品業界の新語に挙げられるほど広まった語で、当時イ・ミンジョン、コ・ヒョンジョン、ソン・ヘギョら女優の澄んだしっとり肌を指して使われた。良いものに「꿀」を付ける用法(꿀잼・꿀팁)と同じ系統。誰が最初に作ったかは出典になく特定しない。", "vi": "꿀 (mật ong) + 피부 (da). Từ này lan rộng đến mức được xếp vào danh sách từ mới của ngành mỹ phẩm năm 2009, khi đó dùng để chỉ làn da trong trẻo căng mọng của các diễn viên như Lee Min-jung, Go Hyun-jung, Song Hye-kyo. Cùng họ với các từ ghép 꿀- chỉ điều tốt (꿀잼, 꿀팁). Không nguồn nào nói ai đặt ra từ này."}'::jsonb, '''너 꿀피부다'', ''꿀피부 비결이 뭐야?''처럼 쓴다. 칭찬으로만 쓰고 비꼬는 뜻은 없다. 화장을 잘했다는 말이 아니라 맨 피부가 좋다는 말이라, 메이크업을 칭찬하려는 자리에서 쓰면 살짝 결이 어긋난다.', '{"de": "Verwendet als 너 꿀피부다 (deine Haut ist toll), 꿀피부 비결이 뭐야? (was ist dein Geheimnis?). Immer ein Kompliment, nie sarkastisch. Da es die nackte Haut lobt und nicht das Make-up, wirkt es leicht daneben, wenn man eigentlich jemandes Make-up loben wollte.", "en": "Used as 너 꿀피부다 (your skin is amazing), 꿀피부 비결이 뭐야? (what''s your secret?). Only ever a compliment — there is no sarcastic sense. Because it praises bare skin rather than makeup, it lands slightly off if what you meant to compliment was someone''s makeup.", "es": "Se usa como 너 꿀피부다 (tienes una piel increíble), 꿀피부 비결이 뭐야? (¿cuál es tu secreto?). Siempre es un cumplido; no tiene lectura sarcástica. Como elogia la piel desnuda y no el maquillaje, suena algo desubicado si lo que querías halagar era el maquillaje de alguien.", "ja": "「너 꿀피부다(肌キレイだね)」「꿀피부 비결이 뭐야?(秘訣は?)」のように使う。褒め言葉としてのみ使い、皮肉の意味はない。メイクではなく素肌を褒める語なので、メイクを褒めたい場面で使うと少しずれて聞こえる。", "vi": "Dùng kiểu 너 꿀피부다 (da bạn đẹp quá), 꿀피부 비결이 뭐야? (bí quyết là gì vậy?). Luôn là lời khen, không có sắc thái mỉa mai. Vì nó khen làn da mộc chứ không khen lớp trang điểm, nên nếu bạn định khen makeup của ai đó thì dùng từ này sẽ hơi lệch."}'::jsonb, array['꿀잼', '쌩얼']::text[], null, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Honey skin (flawless glowing skin)"}, {"lang": "🇯🇵 JA", "text": "ツヤ肌・蜂蜜肌"}, {"lang": "🇨🇳 ZH", "text": "蜂蜜肌 / 水光好皮膚"}, {"lang": "🇻🇳 VI", "text": "Da mật ong"}, {"lang": "🇪🇸 ES", "text": "Piel de miel"}, {"lang": "🇩🇪 DE", "text": "Honighaut"}]'::jsonb),
('521', '과즙상', 'Gwa-Jeup-Sang', 'beauty', 'kpop', '갓 짜낸 과일즙처럼 상큼하고 싱그러운 얼굴', '{"de": "Ein Gesicht so frisch und süß wie frisch gepresster Saft", "en": "A face as fresh and sweet as just-squeezed fruit juice", "es": "Un rostro tan fresco y dulce como zumo recién exprimido", "ja": "搾りたての果汁のようにみずみずしく爽やかな顔立ち", "vi": "Gương mặt tươi mát ngọt ngào như nước ép vừa vắt"}'::jsonb, '[과즙쌍]', '[{"type": "명사", "examples": [{"de": "Sie hat so ein frisches Saftgesicht — wenn sie lacht, ist sie ein Pfirsich.", "es": "Tiene un rostro tan fresco y jugoso; cuando sonríe parece un melocotón.", "ja": "あの子ほんと果汁顔。笑うと完全に桃みたい。", "vi": "Nhỏ đó đúng kiểu mặt ''nước ép'' luôn. Lúc cười y như trái đào.", "eng": "She''s got such a juicy-fresh face — when she smiles she''s literally a peach.", "kor": "쟤 진짜 과즙상이다. 웃을 때 완전 복숭아 같아."}, {"de": "Ich habe kein Saftgesicht, deshalb steht mir so ein rosa Make-up nicht.", "es": "Yo no tengo ese rostro fresco, así que este maquillaje rosa no me favorece.", "ja": "私は果汁顔じゃないから、こういうピンクメイク似合わない。", "vi": "Mặt mình không thuộc kiểu ''nước ép'' nên makeup hồng thế này không hợp.", "eng": "I don''t have that fresh-fruit face, so pink makeup like this doesn''t suit me.", "kor": "나 과즙상 아니라서 이런 핑크 메이크업 안 어울려."}], "definition": "촉촉하고 맑은 피부, 발그레한 볼, 사랑스럽고 생기 있는 분위기가 어우러져 갓 짜낸 과일즙처럼 상큼해 보이는 얼굴이나 인상. 한국에서 얼굴을 ''○○상''으로 분류하는 습관(고양이상·강아지상 등) 중 하나이며, 이목구비가 예쁜지보다 풍기는 느낌이 기준이다. 얼굴을 상·중·하안으로 삼등분했을 때 하안이 상대적으로 짧은 것을 특징으로 꼽는 설명이 많다.", "definition_i18n": {"de": "Ein Gesicht oder Gesamteindruck, der so frisch wirkt wie frisch gepresster Saft — taufrische klare Haut, gerötete Wangen, eine liebenswerte, lebendige Ausstrahlung. Es gehört zur koreanischen Gewohnheit, Gesichter in ○○상-Typen einzuteilen (Katzentyp, Welpentyp), und das Kriterium ist die Ausstrahlung, nicht ob die Züge konventionell hübsch sind. Viele Erklärungen heben ein relativ kurzes unteres Drittel hervor, wenn man das Gesicht in Drittel teilt.", "en": "A face or overall impression that reads as fresh as just-squeezed juice — dewy clear skin, flushed cheeks, a lovable and lively air, all together. It belongs to Korea''s habit of sorting faces into ○○상 types (cat-type, puppy-type), and the criterion is the feeling given off rather than whether the features are conventionally pretty. Many explanations single out a relatively short lower third when the face is divided into upper, middle and lower thirds.", "es": "Un rostro o una impresión general que se lee tan fresca como un zumo recién exprimido: piel limpia y jugosa, mejillas sonrosadas, un aire adorable y lleno de vida. Pertenece a la costumbre coreana de clasificar caras en tipos ○○상 (tipo gato, tipo cachorro), y el criterio es la sensación que transmite, no si los rasgos son convencionalmente bonitos. Muchas explicaciones señalan un tercio inferior relativamente corto al dividir la cara en tercios.", "ja": "しっとり澄んだ肌、ほんのり赤らんだ頬、愛らしく生き生きとした雰囲気が合わさり、搾りたての果汁のようにみずみずしく見える顔や印象。顔を「○○상」と分類する韓国の習慣(猫顔・犬顔など)の一つで、目鼻立ちが整っているかより醸し出す雰囲気が基準。顔を上・中・下顔に三等分したとき下顔が相対的に短いことを特徴に挙げる説明が多い。", "vi": "Gương mặt hoặc ấn tượng tổng thể toát lên vẻ tươi mát như nước ép vừa vắt — da căng mọng trong trẻo, má ửng hồng, khí chất đáng yêu và đầy sức sống. Nó thuộc thói quen phân loại gương mặt theo kiểu ○○상 của người Hàn (kiểu mèo, kiểu cún), và tiêu chí là cảm giác toát ra chứ không phải đường nét có đẹp theo chuẩn hay không. Nhiều cách giải thích nhấn mạnh phần dưới tương đối ngắn khi chia gương mặt thành ba phần."}}]'::jsonb, '''과즙(과일즙)''에 인상·모습을 뜻하는 ''상(相)''을 붙인 말. 원래는 좋아하는 걸그룹 멤버를 ''과즙이 흘러넘칠 것 같은 상큼한 매력''이라고 표현하면서 시작됐다고 전해지며, 나무위키는 만들어진 시점을 대체로 2014년경으로 추정한다 — 다만 이는 추정이고 다른 출처들은 시점을 밝히지 않는다. 파생형 ''과즙미''는 2017년경 공중파 예능에서도 쓰이기 시작했다.', '{"de": "과즙 (Fruchtsaft) plus 상 (相), das Suffix für Erscheinung oder Antlitz. Es soll damit begonnen haben, dass Fans ein Lieblingsmitglied einer Girlgroup als so frisch beschrieben, als wolle der Saft überlaufen. Namuwiki datiert die Prägung auf etwa 2014, doch das ist eine Schätzung, und die anderen Quellen nennen kein Datum. Die Variante 과즙미 tauchte ab etwa 2017 auch in Fernsehshows auf.", "en": "과즙 (fruit juice) plus 상 (相), the suffix for a look or countenance. It is said to have started with fans describing a favourite girl-group member as having a freshness like juice about to spill over. Namuwiki puts its coinage at roughly 2014, but that is an estimate and the other sources give no date. The variant 과즙미 began appearing on network variety shows around 2017.", "es": "과즙 (zumo de fruta) más 상 (相), el sufijo para un aire o semblante. Se dice que empezó con fans describiendo a una integrante favorita de un grupo femenino como alguien con una frescura de zumo a punto de desbordarse. Namuwiki sitúa su acuñación hacia 2014, pero es una estimación y las demás fuentes no dan fecha. La variante 과즙미 empezó a aparecer en programas de variedades en abierto hacia 2017.", "ja": "「과즙(果汁)」に人相・面立ちを表す「상(相)」を付けた語。元は好きなガールグループのメンバーを「果汁があふれ出しそうな爽やかな魅力」と表現したのが始まりとされ、ナムウィキは成立時期をおおむね2014年頃と推定する——ただしこれは推定で、他の出典は時期を示していない。派生形「과즙미」は2017年頃から地上波バラエティでも使われ始めた。", "vi": "과즙 (nước ép trái cây) cộng với 상 (相), hậu tố chỉ tướng mạo, vẻ ngoài. Người ta nói nó khởi đầu từ việc fan mô tả thành viên girlgroup mình thích là có nét tươi mát như nước ép sắp tràn ra. Namuwiki ước đoán từ này ra đời khoảng năm 2014, nhưng đó chỉ là phỏng đoán và các nguồn khác không nêu mốc thời gian. Biến thể 과즙미 bắt đầu xuất hiện trên các chương trình giải trí sóng quốc gia khoảng năm 2017."}'::jsonb, '''과즙상이다'', ''과즙상 메이크업''처럼 쓴다. 칭찬이지만 ''예쁘다''와는 결이 달라서, 또렷하고 성숙한 얼굴에 쓰면 어울리지 않는다 — 어리고 발랄해 보인다는 쪽에 가깝다. 끝의 ''녀'' 때문에 ''과즙녀''는 여성에게만 쓰지만 ''과즙상''은 성별을 가리지 않고 쓰인다. ''과즙미''는 얼굴이 아니라 그 사람이 풍기는 분위기 쪽을 가리킨다.', '{"de": "Verwendet als 과즙상이다 (sie hat ein frisches Saftgesicht), 과즙상 메이크업 (Make-up für diesen Look). Ein Kompliment, aber anders gelagert als 예쁘다 (hübsch): Zu einem scharf geschnittenen, reifen Gesicht passt es nicht, denn es zielt auf jung und spritzig wirkend. Wegen des abschließenden 녀 wird 과즙녀 nur für Frauen verwendet, 과즙상 dagegen geschlechtsunabhängig. 과즙미 meint eher die Ausstrahlung einer Person als das Gesicht selbst.", "en": "Used as 과즙상이다 (she has a juicy-fresh face), 과즙상 메이크업 (makeup for that look). It is a compliment, but a different flavour from 예쁘다 (pretty) — it does not fit a sharp, mature face, since it leans toward looking young and bubbly. Because of its final 녀, 과즙녀 is used only of women, while 과즙상 is used regardless of gender. 과즙미 points at the aura a person gives off rather than the face itself.", "es": "Se usa como 과즙상이다 (tiene un rostro fresco y jugoso), 과즙상 메이크업 (maquillaje para ese look). Es un cumplido, pero de otro tipo que 예쁘다 (guapa): no encaja en un rostro marcado y maduro, porque tira hacia parecer joven y chispeante. Por su 녀 final, 과즙녀 solo se usa para mujeres, mientras que 과즙상 se usa sin distinción de género. 과즙미 apunta al aura que desprende la persona más que a la cara.", "ja": "「과즙상이다(果汁顔だ)」「과즙상 메이크업」のように使う。褒め言葉だが「예쁘다(きれい)」とは質が違い、くっきりした大人っぽい顔に使うと合わない——幼く快活に見えるという方向の語。末尾の「녀(女)」ゆえ「과즙녀」は女性にのみ使うが、「과즙상」は性別を問わず使われる。「과즙미」は顔そのものよりその人の醸す雰囲気を指す。", "vi": "Dùng kiểu 과즙상이다 (bạn ấy có gương mặt tươi mọng), 과즙상 메이크업 (trang điểm theo kiểu đó). Đây là lời khen nhưng khác sắc thái với 예쁘다 (đẹp) — nó không hợp với gương mặt sắc sảo, trưởng thành, vì nghiêng về vẻ trẻ trung, tươi tắn. Vì có chữ 녀 ở cuối, 과즙녀 chỉ dùng cho nữ, còn 과즙상 thì dùng được cho mọi giới. 과즙미 chỉ khí chất toát ra của một người hơn là chính gương mặt."}'::jsonb, array['꿀피부', '추구미', '꾸안꾸']::text[], array['과즙미', '과즙녀']::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Juice face (fresh, dewy, youthful look)"}, {"lang": "🇯🇵 JA", "text": "果汁顔(みずみずしい童顔系)"}, {"lang": "🇨🇳 ZH", "text": "果汁臉(清新水嫩長相)"}, {"lang": "🇻🇳 VI", "text": "Gương mặt ''nước ép'' (tươi mát, trẻ trung)"}, {"lang": "🇪🇸 ES", "text": "Cara de zumo (aspecto fresco y juvenil)"}, {"lang": "🇩🇪 DE", "text": "Saftgesicht (frischer, jugendlicher Look)"}]'::jsonb),
('522', '립덕', 'Rip-Deok', 'beauty', null, '립스틱만 파고드는 덕후 — ''립 + 덕후''', '{"de": "Ein 덕후, dessen Besessenheit Lippenstift ist — ''Lip + 덕후''", "en": "A 덕후 whose obsession is lipstick — ''lip + 덕후''", "es": "Un 덕후 cuya obsesión son los labiales: ''lip + 덕후''", "ja": "リップ専門のオタク——「リップ+덕후」", "vi": "Một 덕후 chuyên về son môi — ''lip + 덕후''"}'::jsonb, '[립떡]', '[{"type": "명사", "examples": [{"de": "Ich bin ein Lippenstift-Nerd, deshalb habe ich denselben Ton von jeder Marke.", "es": "Soy friki de los labiales, así que tengo el mismo tono de todas las marcas.", "ja": "リップオタクだから、同じ色でもブランドごとに全部持ってる。", "vi": "Mình là dân nghiện son nên cùng một màu mà hãng nào cũng có.", "eng": "I''m a lipstick nerd, so I own the same shade from every brand.", "kor": "립덕이라 같은 색도 브랜드별로 다 있어."}, {"de": "Die neue Lippenlinie ist da — die Lippenstift-Nerds drehen durch.", "es": "Salió la nueva línea de labiales; los frikis de labiales están enloquecidos.", "ja": "新作リップ出たって。リップオタクたち大騒ぎ。", "vi": "Dòng son mới ra rồi đó. Hội nghiện son đang náo loạn.", "eng": "The new lip line dropped — the lipstick nerds are losing it.", "kor": "이번 신상 립 나왔대. 립덕들 난리 났어."}], "definition": "화장품 중에서도 특히 립스틱·틴트 같은 립 제품을 좋아해서 모으고, 색과 발림성을 세세하게 따지는 사람. 코덕(코스메틱 덕후) 중에서 관심 분야가 립으로 좁혀진 갈래다. 남이 보기엔 거의 같은 색인 립을 브랜드·제형별로 여러 개 갖고 있는 것이 전형적인 모습이다.", "definition_i18n": {"de": "Jemand, dessen Kosmetikliebe sich genau auf Lippenprodukte verengt — Lippenstifte, Tints —, sie sammelt und über Farbton und Textur haarspalterisch diskutiert. Es ist ein Zweig des 코덕 (Kosmetik-Nerd) mit dem Fokus auf Lippen. Das klassische Zeichen: mehrere Lippenstifte zu besitzen, die für alle anderen dieselbe Farbe sind und sich nur in Marke und Formel unterscheiden.", "en": "Someone whose love of cosmetics narrows specifically to lip products — lipsticks, tints — collecting them and splitting hairs over shade and texture. It is a branch of 코덕 (cosmetics nerd) with the focus pulled in to lips. The classic sign is owning several lipsticks that look like the same colour to everyone else, differing by brand and formula.", "es": "Alguien cuyo amor por la cosmética se estrecha justo hacia los productos de labios —labiales, tintas—, coleccionándolos y hilando finísimo con el tono y la textura. Es una rama del 코덕 (friki de la cosmética) con el foco cerrado en los labios. La señal clásica: tener varios labiales que para los demás son el mismo color, distintos solo en marca y fórmula.", "ja": "化粧品の中でも特にリップスティックやティントなどのリップ製品が好きで集め、色や塗り心地を細かく吟味する人。코덕(コスメオタク)のうち関心がリップに絞られた分派。他人には同じ色にしか見えないリップをブランドや質感ごとに何本も持っているのが典型。", "vi": "Người mà niềm đam mê mỹ phẩm thu hẹp đúng vào các sản phẩm cho môi — son thỏi, son tint — sưu tầm chúng và soi từng chút một về màu sắc lẫn chất son. Đây là một nhánh của 코덕 (dân nghiện mỹ phẩm) với tiêu điểm dồn vào môi. Dấu hiệu kinh điển là sở hữu mấy cây son mà người ngoài nhìn vào thấy y hệt một màu, chỉ khác hãng và chất."}}]'::jsonb, '영어 lip + ''덕후''(일본어 오타쿠에서 온 말). 코덕(코스메틱 덕후)이 먼저 자리 잡은 뒤 관심 분야를 좁혀 부르는 파생어로 쓰이기 시작한 것으로 보이나, 둘 중 어느 쪽이 먼저인지 밝힌 출처는 없어 단정하지 않는다. 2016~2017년 뷰티 매체의 신조어 정리 기사에 이미 등재돼 있다.', '{"de": "Englisch ''lip'' + 덕후 (von japanisch otaku). Es scheint als Verengung von 코덕 (Kosmetik-Nerd) entstanden zu sein, nachdem sich jenes Wort etabliert hatte, doch keine Quelle sagt, was zuerst da war — das wird hier also nicht als gesichert behauptet. In Neuwort-Übersichten von Beauty-Magazinen tauchte es bereits 2016–2017 auf.", "en": "English ''lip'' + 덕후 (from Japanese otaku). It appears to have arisen as a narrowing of 코덕 (cosmetics nerd) once that word was established, but no source states which came first, so this is not asserted as settled. It was already listed in beauty-magazine neologism round-ups in 2016–2017.", "es": "Inglés ''lip'' + 덕후 (del japonés otaku). Parece haber surgido como un estrechamiento de 코덕 (friki de la cosmética) una vez asentada esa palabra, pero ninguna fuente dice cuál vino primero, así que no se afirma como cerrado. Ya figuraba en los recopilatorios de neologismos de revistas de belleza en 2016-2017.", "ja": "英語 lip +「덕후」(日本語のオタク由来)。코덕(コスメオタク)が定着した後、関心分野を狭めた派生語として使われ始めたと見られるが、どちらが先かを明記した出典はなく断定しない。2016~2017年のビューティー誌の新語まとめ記事にすでに載っている。", "vi": "Tiếng Anh ''lip'' + 덕후 (từ otaku tiếng Nhật). Có vẻ nó nảy sinh như một cách thu hẹp của 코덕 (dân nghiện mỹ phẩm) sau khi từ đó đã phổ biến, nhưng không nguồn nào nói từ nào có trước, nên điều này không được khẳng định chắc chắn. Nó đã có mặt trong các bài tổng hợp từ mới của tạp chí làm đẹp năm 2016–2017."}'::jsonb, '''나 립덕이야'', ''립덕 인증''처럼 쓴다. 코덕과 마찬가지로 자기를 낮추는 말이 아니라 자랑에 가깝게 쓴다. 발음은 [립떡]으로 뒤 글자가 된소리가 된다.', '{"de": "Verwendet als 나 립덕이야 (ich bin ein Lippenstift-Nerd), 립덕 인증 (Beweis dafür — meist ein Foto der Sammlung). Wie 코덕 trägt man es als Angeberei, nicht als Herabsetzung. Zur Aussprache: [립떡], die zweite Silbe wird gespannt.", "en": "Used as 나 립덕이야 (I''m a lipstick nerd), 립덕 인증 (proof I''m a lipstick nerd — usually a photo of the collection). Like 코덕, it is worn as a boast rather than a put-down. Note the pronunciation: [립떡], with the second syllable tensed.", "es": "Se usa como 나 립덕이야 (soy friki de los labiales), 립덕 인증 (prueba de que lo soy, normalmente una foto de la colección). Como 코덕, se lleva con orgullo, no como reproche. Ojo a la pronunciación: [립떡], con la segunda sílaba tensa.", "ja": "「나 립덕이야(私リップオタク)」「립덕 인증(リップオタク認証=コレクション写真)」のように使う。코덕と同じく自虐ではなく自慢に近い。発音は[립떡]で後ろの字が濃音になる。", "vi": "Dùng kiểu 나 립덕이야 (mình là dân nghiện son), 립덕 인증 (bằng chứng nghiện son — thường là ảnh chụp bộ sưu tập). Giống 코덕, từ này được dùng để khoe chứ không phải để tự hạ thấp. Lưu ý cách phát âm: [립떡], âm tiết sau bị căng."}'::jsonb, array['코덕', '하울', '인생템']::text[], null, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Lipstick nerd / lip-product collector"}, {"lang": "🇯🇵 JA", "text": "リップオタク"}, {"lang": "🇨🇳 ZH", "text": "口紅控"}, {"lang": "🇻🇳 VI", "text": "Dân nghiện son"}, {"lang": "🇪🇸 ES", "text": "Friki de los labiales"}, {"lang": "🇩🇪 DE", "text": "Lippenstift-Nerd"}]'::jsonb),
('523', '7스킨법', 'Chil-Seu-Kin-Beop', 'beauty', null, '토너를 얇게 일곱 번 겹쳐 바르는 수분 충전법', '{"de": "Die Sieben-Toner-Methode — Toner siebenmal dünn schichten", "en": "The seven-skin method — layering toner on seven thin times", "es": "El método de las siete capas: aplicar tónico siete veces en capas finas", "ja": "化粧水を薄く七回重ね塗りする保湿法", "vi": "Phương pháp 7 lớp toner — thoa toner mỏng bảy lần"}'::jsonb, '[칠스킨뻡]', '[{"type": "명사", "examples": [{"de": "Meine Haut ist so trocken, dass ich vor dem Schlafen die Sieben-Toner-Methode mache.", "es": "Tengo la piel muy seca, así que últimamente hago el método de las siete capas antes de dormir.", "ja": "乾燥がひどくて最近寝る前に7スキンやってる。", "vi": "Da khô quá nên dạo này trước khi ngủ mình làm 7 lớp toner.", "eng": "My skin''s so dry I''ve been doing the seven-skin method before bed.", "kor": "건조해서 요즘 자기 전에 7스킨법 해."}, {"de": "Bringt die Sieben-Toner-Methode wirklich was? Was ist der Unterschied zu einfach Feuchtigkeitscreme?", "es": "¿El método de las siete capas funciona de verdad? ¿En qué se diferencia de ponerse crema hidratante?", "ja": "7スキンって本当に効果あるの? 保湿クリーム塗るのと何が違うの?", "vi": "7 lớp toner có hiệu quả thật không? Khác gì với thoa kem dưỡng ẩm?", "eng": "Does the seven-skin method actually work? How''s it different from just using moisturizer?", "kor": "7스킨법 진짜 효과 있어? 그냥 수분크림 바르는 거랑 뭐가 달라?"}], "definition": "스킨(토너)을 한 번에 듬뿍 바르는 대신, 손에 조금씩 덜어 두드려 흡수시키기를 일곱 번 반복하는 스킨케어 방법. 보통 첫 번째는 화장솜으로 닦아내고 나머지 여섯 번을 손으로 덧바른다. 알코올이 없고 묽은 토너를 쓰는 것이 기본이다. 속당김이 심한 사람들 사이에서 퍼진 방법이지만, 실제 효과를 두고는 뷰티 매체와 의료 쪽 의견이 갈린다.", "definition_i18n": {"de": "Eine Pflegeroutine, bei der man den Toner nicht einmal großzügig aufträgt, sondern eine kleine Menge einklopft und das siebenmal wiederholt. Üblicherweise wird der erste Durchgang mit einem Wattepad aufgetragen, die übrigen sechs mit der Hand eingeklopft. Standard ist ein alkoholfreier, wässriger Toner. Sie verbreitete sich unter Menschen mit spannender, dehydrierter Haut, wobei Beauty-Medien und medizinische Stimmen uneins sind, ob sie tatsächlich wirkt.", "en": "A skincare routine where instead of applying toner generously once, you tap a small amount into the skin and repeat seven times. Typically the first pass is wiped on with a cotton pad and the remaining six are patted on by hand. An alcohol-free, watery toner is the standard choice. It spread among people with tight, dehydrated skin, though beauty media and medical commentators disagree about whether it actually works.", "es": "Una rutina en la que, en vez de aplicar el tónico generosamente una vez, te pones un poco y lo das a golpecitos, repitiendo siete veces. Normalmente la primera pasada se hace con un disco de algodón y las seis restantes con la mano. Lo estándar es un tónico ligero y sin alcohol. Se extendió entre quienes tienen la piel tirante y deshidratada, aunque los medios de belleza y los comentaristas médicos discrepan sobre si de verdad funciona.", "ja": "化粧水(トナー)を一度にたっぷり塗る代わりに、少量ずつ手に取って叩き込むのを七回繰り返すスキンケア法。通常は一回目をコットンで拭き取り、残る六回を手で重ね塗りする。アルコール無添加でさらっとした化粧水を使うのが基本。内側の乾燥がひどい人の間で広まった方法だが、実際の効果についてはビューティー媒体と医療側で意見が分かれる。", "vi": "Một quy trình dưỡng da mà thay vì thoa toner thật nhiều một lần, bạn lấy một ít vỗ cho thấm rồi lặp lại bảy lần. Thông thường lượt đầu lau bằng bông tẩy trang, sáu lượt còn lại vỗ bằng tay. Lựa chọn tiêu chuẩn là toner loãng, không cồn. Cách này lan rộng trong nhóm người có da căng khô thiếu nước, dù báo làm đẹp và giới y khoa bất đồng về chuyện nó có thật sự hiệu quả hay không."}}]'::jsonb, '숫자 7 + 스킨(토너) + 법(방법). 배우 이하늬의 피부 관리 비법으로 알려지면서 퍼졌다는 서술이 여러 출처에 나오지만, 이하늬가 이 방법을 만들었다고 밝힌 출처는 없어 ''알려지며 퍼졌다''까지만 말할 수 있다. 왜 하필 일곱 번인지에 대한 근거도 출처마다 제시되지 않는다. 2017년 무렵 뷰티 매체들이 일제히 다루면서 이름이 굳었다.', '{"de": "Die Zahl 7 + 스킨 (Toner) + 법 (Methode). Mehrere Quellen sagen, sie verbreitete sich, nachdem sie als Hautpflegegeheimnis der Schauspielerin Lee Ha-nee bekannt wurde, doch keine behauptet, sie habe sie erfunden — belegbar ist nur die Verbreitung. Auch erklärt keine Quelle, warum ausgerechnet sieben. Der Name setzte sich um 2017 durch, als koreanische Beauty-Medien gleichzeitig darüber berichteten.", "en": "The number 7 + 스킨 (toner) + 법 (method). Several sources say it spread after being reported as actor Lee Ha-nee''s skincare secret, but none claims she invented it, so only the spreading can be stated. Nor does any source explain why seven specifically. The name settled around 2017, when Korean beauty media covered it all at once.", "es": "El número 7 + 스킨 (tónico) + 법 (método). Varias fuentes dicen que se extendió tras difundirse como el secreto de belleza de la actriz Lee Ha-nee, pero ninguna afirma que ella lo inventara, así que solo puede afirmarse la difusión. Tampoco ninguna fuente explica por qué siete en concreto. El nombre cuajó hacia 2017, cuando los medios de belleza coreanos lo cubrieron a la vez.", "ja": "数字の7+스킨(化粧水)+법(法)。女優イ・ハニの肌管理の秘訣として知られて広まったという記述が複数の出典にあるが、彼女が考案したとする出典はないため「知られて広まった」までしか言えない。なぜ七回なのかの根拠も出典に示されていない。2017年頃にビューティー媒体が一斉に取り上げて名称が定着した。", "vi": "Số 7 + 스킨 (toner) + 법 (phương pháp). Nhiều nguồn nói nó lan rộng sau khi được đưa tin là bí quyết dưỡng da của diễn viên Lee Ha-nee, nhưng không nguồn nào khẳng định cô sáng tạo ra nó, nên chỉ có thể nói về việc nó lan rộng. Cũng không nguồn nào giải thích vì sao lại là bảy lần. Tên gọi định hình khoảng năm 2017, khi báo làm đẹp Hàn đồng loạt đưa tin."}'::jsonb, '''7스킨법 한다'', ''7스킨 하고 잤어''처럼 쓴다. 줄여서 ''7스킨''이라고만 해도 통한다. 숫자로 쓰지만 읽을 땐 ''칠스킨법''이다. 효과를 두고는 의견이 갈리는 말이라 — 뷰티 매체는 수분 보충법으로 소개하고, 한의사 칼럼 등 의료 쪽에서는 효과를 반박한다 — 단정적으로 권하기보다 ''나는 이렇게 한다'' 정도로 말하는 경우가 많다.', '{"de": "Verwendet als 7스킨법 한다 (ich mache die Sieben-Toner-Methode), 7스킨 하고 잤어 (ich habe vor dem Schlafen sieben Toner gemacht). Die Kurzform 7스킨 funktioniert ebenso. Geschrieben mit Ziffer, gelesen als 칠스킨법. Die Meinungen zur Wirksamkeit gehen auseinander — Beauty-Medien stellen es als Feuchtigkeitsroutine vor, medizinische Kolumnen widersprechen deutlich —, daher formulieren es die meisten als das, was sie selbst tun, statt es rundheraus zu empfehlen.", "en": "Used as 7스킨법 한다 (I do the seven-skin method), 7스킨 하고 잤어 (I did seven-skin before bed). Shortening it to just 7스킨 works fine. It is written with a numeral but read 칠스킨법. Opinions split on whether it works — beauty media present it as a hydration routine, while medical columns push back hard — so people tend to phrase it as what they personally do rather than recommend it flatly.", "es": "Se usa como 7스킨법 한다 (hago el método de las siete capas), 7스킨 하고 잤어 (me hice las siete capas antes de dormir). Acortarlo a 7스킨 funciona igual. Se escribe con cifra pero se lee 칠스킨법. Las opiniones se dividen sobre su eficacia —los medios de belleza lo presentan como rutina hidratante y las columnas médicas lo rebaten con dureza—, así que la gente suele plantearlo como lo que hace ella, más que recomendarlo sin más.", "ja": "「7스킨법 한다(7スキンやってる)」「7스킨 하고 잤어(7スキンして寝た)」のように使う。縮めて「7스킨」だけでも通じる。数字で書くが読みは「칠스킨법」。効果については意見が割れる語で——ビューティー媒体は保湿法として紹介し、韓医師のコラムなど医療側は効果を否定する——断定的に勧めるより「私はこうしてる」程度に言うことが多い。", "vi": "Dùng kiểu 7스킨법 한다 (mình làm 7 lớp toner), 7스킨 하고 잤어 (làm 7 lớp toner rồi đi ngủ). Rút gọn thành 7스킨 cũng được. Viết bằng chữ số nhưng đọc là 칠스킨법. Ý kiến chia rẽ về hiệu quả — báo làm đẹp giới thiệu như một quy trình cấp ẩm, còn các chuyên mục y khoa phản bác mạnh — nên người ta thường nói theo kiểu ''mình làm vậy'' hơn là khuyên dứt khoát."}'::jsonb, array['팩토', '닦토', '수부지']::text[], array['7스킨', '칠스킨법']::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Seven-skin method (toner layering)"}, {"lang": "🇯🇵 JA", "text": "7スキン法(化粧水の重ね塗り)"}, {"lang": "🇨🇳 ZH", "text": "七次化妝水疊擦法"}, {"lang": "🇻🇳 VI", "text": "Phương pháp 7 lớp toner"}, {"lang": "🇪🇸 ES", "text": "Método de las siete capas de tónico"}, {"lang": "🇩🇪 DE", "text": "Sieben-Toner-Methode"}]'::jsonb)
